INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1700, '[Infographic] Thủy Điện Việt Nam', 'infographic-thuy-dien-viet-nam', '<p>Thủy điện Việt Nam là một đề tài xã hội nóng hỏi gần đây. Chúng ta hãy cùng nhìn lại thật rõ tác động của thủy điện Việt Nam hiện nay là như thế nào. Ngoài ra, quá trình hình thành và phát triển từ đầu đến hàng trăm nhà máy hiện nay. Những thông tin hữu ích sẽ được trình bày một cách trực quan và dễ hiểu nhất qua infographic.</p>
<h2>Infographic Thủy Điện Việt Nam</h2>
<p><figure id="attachment_1702" aria-describedby="caption-attachment-1702" style="width: 1280px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1702" src="https://media.huynhhieutravel.com/Thủy-Điện-Việt-Nam.jpg" alt="Thủy điện Việt Nam" width="1280" height="5906" srcset="https://media.huynhhieutravel.com/Thủy-Điện-Việt-Nam.jpg 1280w, https://media.huynhhieutravel.com/Thủy-Điện-Việt-Nam-768x3544.jpg 768w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption id="caption-attachment-1702" class="wp-caption-text">Thủy điện Việt Nam</figcaption></figure></p>
', 'Thủy điện Việt Nam là một đề tài xã hội nóng hỏi gần đây. Chúng ta hãy cùng nhìn lại thật rõ tác động của thủy điện Việt Nam hiện nay là như thế nào. Ngoài ra, quá trình hình thành và phát triển từ đầu đến hàng trăm nhà máy hiện nay. Những thông [&hellip;]', 1701, 'post', '2018-09-03 14:53:52', '2023-04-23 12:35:01');
