INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1516, 'Đường Hầm Điêu Khắc (Đường Hầm Đất Sét) Đà Lạt', 'duong-ham-dieu-khac-da-lat', '<p><strong>Đường hầm điêu khắc</strong> còn có nhiều tên gọi khác nhau như đường hầm đất sét, đường hầm đất đỏ,&#8230; Nhưng dù với tên gọi nào thì nó vẫn là một điểm du lịch thu hút khách tham quan của Đà Lạt. Nơi đây có hàng trăm tiểu cảnh khác nhau khắc những cảnh quan xinh đẹp nổi tiếng của Đà Lạt: Thác Datanla, núi LangBiang, thung lũng tình yêu,&#8230;</p>
<h2>Thông tin Đường hầm điêu khắc</h2>
<p>Đường hầm điêu khắc nằm cách trung tâm thành phố Đà Lạt khoảng 13km, theo hướng thác Datanla và hồ Tuyền Lâm. Nơi đây được xây dựng với chiều dài khoảng 2km với nhiều tiểu cảnh làm bằng đất sét đại diện cho Đà Lạt.</p>
<p><figure id="attachment_1523" aria-describedby="caption-attachment-1523" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1523" src="https://media.huynhhieutravel.com/Đường-Hâm-Điều-Khắc2.jpg" alt="Chuông khổng lồ" width="960" height="720" srcset="https://media.huynhhieutravel.com/Đường-Hâm-Điều-Khắc2.jpg 960w, https://media.huynhhieutravel.com/Đường-Hâm-Điều-Khắc2-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1523" class="wp-caption-text">Chuông khổng lồ</figcaption></figure></p>
<p><strong>Địa chỉ</strong>:&nbsp;Phường 4, Thành phố Đà Lạt, Lâm Đồng.</p>
<p><strong>Giờ mở cửa</strong>: 7h30-17h00.</p>
<p><strong>Email:</strong>&nbsp;ceo@dalatstar.com</p>
<p><strong>Web:</strong>&nbsp;www.dalatstar.com</p>
<p><iframe style="border: 0;" src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d62469.1717647647!2d108.37623998842678!3d11.882565743571218!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31716b38c34667bf%3A0x3d987ff049b1b859!2zxJDGsOG7nW5nIEjhuqdtIMSQacOqdSBLaOG6r2M!5e0!3m2!1svi!2s!4v1534239105120" width="600" height="450" frameborder="0" allowfullscreen="allowfullscreen"></iframe></p>
<h4>Nguồn gốc Đường hầm điêu khắc</h4>
<p>Đường hầm điêu khắc là công trình do một tay anh Trịnh Bá Dũng dựng nên. Bạn đầu anh học về kinh tế ở đại học Hàng Hải và có thêm 3 năm du học ở Đức. Nhưng vì đam mê kiến trúc cổ anh đã trở về Việt Nam thực hiện những dự án của mình.</p>
<p>Sau một thời gian đóng đô làm việc ở Đà Lạt về xây dựng. Anh Dũng đã nhìn thấy điểm chung du lịch Đà Lạt là chưa tạo ra được nét độc đáo riêng của mình. Và với lợi thế về đất đỏ bazan anh hoàn toàn có thể tạo nên những kiến trúc độc đáo với nét riêng. Và từ đó anh bắt đầu ấp ủ dự định của mình.</p>
<p><figure id="attachment_1524" aria-describedby="caption-attachment-1524" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1524" src="https://media.huynhhieutravel.com/Đường-Hâm-Điều-Khắc3.jpg" alt="Tiểu cảnh trong đường hầm đất sét" width="960" height="720" srcset="https://media.huynhhieutravel.com/Đường-Hâm-Điều-Khắc3.jpg 960w, https://media.huynhhieutravel.com/Đường-Hâm-Điều-Khắc3-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1524" class="wp-caption-text">Tiểu cảnh trong đường hầm đất sét</figcaption></figure></p>
<p>Anh Dũng hồi tưởng lại:</p>
<p><em>“Năm 2008, chúng tôi bắt đầu thực hiện công trình này, lúc ấy ở đây không đường, không điện, không nước, chúng tôi bắt đầu từ con số không. Trải qua nhiều lần thất bại, ý tưởng ban đầu cũng thay đổi khi vào thực tế, tôi “đốt” gần hết gia sản vào những việc mà bạn bè cho là điên rồ. Nhiều đêm, dù trời lạnh, một ý tưởng lóe lên trong đầu, tôi tung mền chạy ra vườn thọc tay vào đống đất sét lạnh vầy vò đến sáng. Cái khó nhất là tìm ra công nghệ pha trộn đất sét để công trình có thể chịu được nắng mưa và bền như sản phẩm đất nung”</em>.</p>
<p>Và đến năm 2012, Đường hầm điêu khắc bắt đầu ra đời. Và chúng còn có tên gọi là đường hầm đất sét vì những hạng mục công trình đều làm bằng đất sét từ đất đỏ bazan của chính vùng đất Đà Lạt.</p>
<h3>Những kỷ lục của Đường hầm điêu khắc</h3>
<p>Đường hầm điêu khắc đang nắm giữ 2 kỷ lục Việt Nam đó là:</p>
<ul>
<li>Ngôi nhà đất đỏ bazan không nung đầu tiên ở Việt Nam.</li>
<li>Ngôi nhà đất đỏ bazan không nung lớn nhất ở Việt Nam.</li>
</ul>
<p>Ngôi nhà này có diện tích khoảng 90m2. Trên mái nhà của ngôi nhà còn khắc hình bản đồ Việt Nam với chủ quyền hoàng sa và trường sa.</p>
<p><figure id="attachment_1520" aria-describedby="caption-attachment-1520" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1520" src="https://media.huynhhieutravel.com/Đường-Hầm-Đất-Sét2.jpg" alt="Nghệ nhân chơi trống thép" width="960" height="720" srcset="https://media.huynhhieutravel.com/Đường-Hầm-Đất-Sét2.jpg 960w, https://media.huynhhieutravel.com/Đường-Hầm-Đất-Sét2-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1520" class="wp-caption-text">Nghệ nhân chơi trống thép</figcaption></figure></p>
<h2>Đường hầm điêu khắc có gì chơi?</h2>
<p>Đường hầm điêu khắc còn được cho là một Đà Lạt thu nhỏ lại bằng mô hình đất sét. Nơi đây có rất nhiều tiểu cảnh nổi tiếng ở Đà Lạt được điêu khắc lại trên mặt đất sét: Hồ Xuân Hương, nhà ga Đà Lạt, núi LangBiang, sân bay Liên Khương,&#8230;</p>
<p>Và các tiểu cảnh vật dụng thú vị được mô hình hóa bằng đất sét khổng lồ như chiếc xe máy khổng lồ, bài hát Đà Lạt Hoàng Hôn của tác giả Minh Kỳ cũng được khắc lên đây, chiếc piano khổng lồ,&#8230;</p>
<p><figure id="attachment_1527" aria-describedby="caption-attachment-1527" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1527" src="https://media.huynhhieutravel.com/Đường-hâm-điêu-khắc6.jpg" alt="Bài hát Hoàng Hôn Đà Lạt được khắc ở đường hầm điêu khắc" width="960" height="720" srcset="https://media.huynhhieutravel.com/Đường-hâm-điêu-khắc6.jpg 960w, https://media.huynhhieutravel.com/Đường-hâm-điêu-khắc6-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1527" class="wp-caption-text">Bài hát Hoàng Hôn Đà Lạt được khắc ở đường hầm điêu khắc</figcaption></figure></p>
<p>Nơi đây còn có những con đường cẩm tú cầu xinh đẹp. Bạn sẽ bị choáng ngợp bởi những con đường đầy cẩm tú cầu ở nơi đây.</p>
<p>Ngoài ra ở đây có nhiều điểm bán hàng lưu niệm khác nhau. Bạn cũng có thể thuê đồ dân tộc để hóa thân thành một thanh niên miền núi lạc vào Đường hầm điêu khắc.</p>
<h2>Cách đi đến Đường hầm điêu khắc</h2>
<p>Đường hầm điêu khắc cách trung tâm thành phố Đà Lạt khoảng 13km. Bạn đi theo hướng thác Datanla.</p>
<p>Địa chỉ:&nbsp;Phường 4, Thành phố Đà Lạt, Lâm Đồng</p>
<p>Các bạn có thể nhấn vào đường link và điền vị trí của bạn vào để nhận chỉ đường: <a href="https://www.google.com/maps/dir//%C4%90%C6%B0%E1%BB%9Dng+H%E1%BA%A7m+%C4%90i%C3%AAu+Kh%E1%BA%AFc,+Ph%C6%B0%E1%BB%9Dng+4,+Th%C3%A0nh+ph%E1%BB%91+%C4%90%C3%A0+L%E1%BA%A1t,+L%C3%A2m+%C4%90%E1%BB%93ng,+Vi%E1%BB%87t+Nam/@10.9636692,106.0011095,8z/data=!4m8!4m7!1m0!1m5!1m1!1s0x31716b38c34667bf:0x3d987ff049b1b859!2m2!1d108.4112597!2d11.8825679">Đường đi đến đường hầm điêu khắc</a></p>
<p><figure id="attachment_1519" aria-describedby="caption-attachment-1519" style="width: 540px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-1519" src="https://media.huynhhieutravel.com/Đường-Hâm-Đất-Sét2.jpg" alt="Toàn cảnh 360 độ Đường hầm điêu khắc" width="540" height="960"><figcaption id="caption-attachment-1519" class="wp-caption-text">Toàn cảnh 360 độ Đường hầm điêu khắc</figcaption></figure></p>
<h2>Kinh nghiệm đi Đường hầm điêu khắc</h2>
<ul>
<li>Bạn nên chuẩn bị đầy đủ nước và thức ăn. Thức ăn ở đây không quá ngon, bạn có thể mua đồ ăn nhẹ cho chuyến đi picnic này: bánh mì, snack,… Vì đoạn đường đi bộ đến gần 2km nên bạn hãy chuẩn bị đủ nước. Bạn có thể mang dù và nón sẽ tránh nắng tốt hơn.</li>
<li>Nếu đi du lịch theo đoàn bạn sẽ được chụp miễn phí và tặng 1 tấm hình tập thể trước đường hầm. Bạn cứ hỏi lấy tấm ảnh đó khi về nhé!</li>
</ul>
<p><figure id="attachment_1521" aria-describedby="caption-attachment-1521" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1521" src="https://media.huynhhieutravel.com/Đường-Hâm-Đất-Sét-Đà-Lạt.jpg" alt="Khách du lịch tham quan đường hầm điêu khắc" width="960" height="720" srcset="https://media.huynhhieutravel.com/Đường-Hâm-Đất-Sét-Đà-Lạt.jpg 960w, https://media.huynhhieutravel.com/Đường-Hâm-Đất-Sét-Đà-Lạt-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1521" class="wp-caption-text">Khách du lịch tham quan đường hầm điêu khắc</figcaption></figure></p>
<h3>Thời điểm thích hợp đi Đường hầm điêu khắc</h3>
<p>Đường hầm điêu khắc gần như mở quanh năm và có thời gian mở cửa từ 7h30 sáng đến 5h00 chiều. Nhưng tốt nhất bạn hãy tránh đi vào những ngày mưa rào nặng hạt. Bạn cũng nên tránh đến đây vào dịp lễ nào đó để tránh hàng nghìn người chen lấn đông đúc! Và thời điểm tốt nhất để đi trong ngày là sáng sớm hoặc chiều. Bạn nên tránh cái nắng nóng giờ trưa cao điểm khi đến đây.</p>
<p><figure id="attachment_1525" aria-describedby="caption-attachment-1525" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1525" src="https://media.huynhhieutravel.com/Đường-hâm-điêu-khắc4.jpg" alt="Khung cảnh thiên nhiên xinh đẹp trong đường hầm điêu khắc" width="960" height="720" srcset="https://media.huynhhieutravel.com/Đường-hâm-điêu-khắc4.jpg 960w, https://media.huynhhieutravel.com/Đường-hâm-điêu-khắc4-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1525" class="wp-caption-text">Khung cảnh thiên nhiên xinh đẹp trong đường hầm điêu khắc</figcaption></figure></p>
<h3>Giá vé vào cổng Đường hầm điêu khắc</h3>
<p>Giá vé vào cổng là 60k/người lớn. Trẻ em là 30k/bé.</p>
<p><em>Lưu ý: Thông tin được cập nhật vào tháng 8 năm 2018.</em></p>
<p><figure id="attachment_1526" aria-describedby="caption-attachment-1526" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1526" src="https://media.huynhhieutravel.com/Đường-hâm-điêu-khắc5.jpg" alt="Con đường cẩm tú cầu" width="960" height="720" srcset="https://media.huynhhieutravel.com/Đường-hâm-điêu-khắc5.jpg 960w, https://media.huynhhieutravel.com/Đường-hâm-điêu-khắc5-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1526" class="wp-caption-text">Con đường cẩm tú cầu</figcaption></figure></p>
<h3>Gợi ý lịch trình tham quan Đường hầm điêu khắc một ngày cho bạn!</h3>
<h4><em><strong>Thác Datanla &#8211; Thiền Viện Trúc Lâm &#8211; Đường Hầm Đất Sét &#8211; Hồ Tuyền Lâm</strong></em></h4>
<p>Chúng ta sẽ đi thác Datanla vào buổi sáng để tham quan. Leo dốc vào buổi sáng tránh cái nắng nóng sẽ hiệu quả hơn. Sau đó đến Thiền Viện Trúc Lâm Đà Lạt gần đó tham quan. Nơi đây ngoài những kiến trúc độc đáo của phái Trúc Lâm Yên Tử bạn sẽ còn được tham quan một vườn hoa thu nhỏ của Đà Lạt.</p>
<p>Tiếp theo chúng ta đến Đường hầm điêu khắc. Sau khi tham quan, đến chiều, chúng ta về lại hồ Tuyền Lâm. Bạn có thể thuê thuyền dạo quanh 1 vòng hồ. Bạn sẽ rất kinh ngạc bởi cảnh quan bên trong hồ Tuyền Lâm.</p>
<p><figure id="attachment_1530" aria-describedby="caption-attachment-1530" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1530" src="https://media.huynhhieutravel.com/Đường-Hâm-Điều-Khắc-Đà-Lạt.jpg" alt="Đường hầm điêu khắc đà lạt" width="960" height="720" srcset="https://media.huynhhieutravel.com/Đường-Hâm-Điều-Khắc-Đà-Lạt.jpg 960w, https://media.huynhhieutravel.com/Đường-Hâm-Điều-Khắc-Đà-Lạt-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1530" class="wp-caption-text">Đường hầm điêu khắc đà lạt</figcaption></figure></p>
<h2>Review Đường hầm điêu khắc</h2>
<p>Cảnh quan nơi đây chủ yếu là nhiều mô hình bằng đất sét rộng lớn. Ngoài ra có nhiều hoa cẩm tú cầu xinh đẹp. Nhưng cảnh quan còn bị đơn điệu và sơ sài. Nếu bạn không yêu kiến trúc thì những mô hình điêu khắc sẽ rất nhàm chán. Đánh giá: 6/10 điểm.</p>
<p>Bạn hãy cân nhắc đi địa điểm này, nếu không có nhiều thời gian cho Đà Lạt thì đừng nên đến đây!</p>
<p><figure id="attachment_1528" aria-describedby="caption-attachment-1528" style="width: 960px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1528" src="https://media.huynhhieutravel.com/Đường-hâm-điêu-khắc7.jpg" alt="Hàng cẩm tú cầu được trồng" width="960" height="720" srcset="https://media.huynhhieutravel.com/Đường-hâm-điêu-khắc7.jpg 960w, https://media.huynhhieutravel.com/Đường-hâm-điêu-khắc7-768x576.jpg 768w" sizes="(max-width: 960px) 100vw, 960px" /><figcaption id="caption-attachment-1528" class="wp-caption-text">Hàng cẩm tú cầu được trồng</figcaption></figure></p>
<h3>Đánh giá của khách du lịch về Đường hầm điêu khắc</h3>
<p>Bạn Phương Thảo Nguyễn đánh giá 4/5: Khu du lịch được đầu tư khá tốt, ở đây có nhiều cảnh đẹp. Điểm ăn uống sạch sẽ, mang cảm giác thoải mái. Điểm giữ xe là của ban quản lý nên khá thích,&#8230;</p>
<p>Bạn Phúc Trần đánh giá 5/5: Nơi này rất đẹp, rất nhiều quang cảnh tuyệt vời. Và bạn ấy có để lại Lưu ý cho chúng ta: Ở đây khá nhiều bùn đất nên phải chú ý. Bãi giữ xe rộng nhưng có quy định về phí gửi xe.</p>
<p><figure id="attachment_1531" aria-describedby="caption-attachment-1531" style="width: 373px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1531" src="https://media.huynhhieutravel.com/Review-Đường-Hầm-Điêu-Khắc.png" alt="Review đường hầm điêu khắc của khách du lịch" width="373" height="503"><figcaption id="caption-attachment-1531" class="wp-caption-text">Review đường hầm điêu khắc của khách du lịch</figcaption></figure></p>
<p><em><strong>Video clip Làng Đất Sét qua góc nhìn flycam</strong></em></p>
<p><iframe title="Làng Đất Sét - Đường hầm điêu khắc dưới lòng đất ở Đà Lạt | ZaiTri" width="800" height="450" src="https://www.youtube.com/embed/c6-XRZT7suA?feature=oembed" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></p>
