INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1438, 'Trải nghiệm tuyệt vời ở Hội trại Tuổi trẻ Phật giáo 2018', 'trai-nghiem-tuyet-voi-o-hoi-trai-tuoi-tre-phat-giao-2018', '<p>Hội trại Tuổi trẻ Phật giáo 2018 là một khóa tu tập được diễn ra vào hè tháng 7 trong 3 ngày. Đặc biệt, tôi đã có một trải nghiệm tuyệt vời ở Hội trại Tuổi trẻ Phật giáo năm 2018 với lần tổ chức thứ 13 này. Tôi cùng với hơn 1000 trại sinh khác đã sinh hoạt, vui chơi và học tập giáo lý Phật giáo đầy ý nghĩa. Chúng tôi đã có những buổi trò chuyện tuyệt vời về chủ đề Tuổi Thanh Xuân của kỳ hội trại năm nay. Nó không hẳn là một chuyến học tập về tôn giáo nữa, mà gần như là một hành trình du lịch tuyệt vời của tôi. Tôi đã được lắng sâu lòng mình trong thiền định, được bùng nổ cùng hơn 1000 bạn thanh thiếu niên từ 14 đến 32 tuổi. Hãy cùng tôi tìm hiểu, hội trại này có gì đặc biệt mà lại thu hút nhiều bạn trẻ tham gia đến vậy?</p>
<h2>Tôi đã tham gia Hội trại Tuổi trẻ Phật giáo lần thứ 13</h2>
<p>Tôi may mắn được đồng hành cùng Hội trại Tuổi trẻ Phật giáo lần thứ 13 này khi là một trong những trại sinh cuối cùng đăng ký. Nó đã kết thúc sớm hơn hạn chót đăng ký vì có quá nhiều đơn nộp online đăng ký. Chi tiết về hội trại:</p>
<blockquote class="wp-embedded-content" data-secret="A62FSal1Gm"><p><a href="https://huynhhieutravel.com/hoi-trai-tuoi-tre-phat-giao/">Hội Trại Tuổi Trẻ Phật Giáo 2018 | Tuổi Thanh Xuân</a></p></blockquote>
<p><iframe class="wp-embedded-content" sandbox="allow-scripts" security="restricted" style="position: absolute; clip: rect(1px, 1px, 1px, 1px);" title="&#8220;Hội Trại Tuổi Trẻ Phật Giáo 2018 | Tuổi Thanh Xuân&#8221; &#8212; Huỳnh Hiếu Travel" src="https://huynhhieutravel.com/hoi-trai-tuoi-tre-phat-giao/embed/#?secret=qELR9oCeXD#?secret=A62FSal1Gm" data-secret="A62FSal1Gm" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>
<h3>Hãy nghỉ lại một đêm ở chùa Vĩnh Nghiêm nếu bạn ở xa</h3>
<p>Hơn 1000 người tham gia sẽ được chia đều thành 4 cụm trại khác nhau với các tên gọi: Thanh Tịnh, Từ Bi, Trí Tuê và Tinh Tấn. Mỗi tiểu trại lại được đánh số từ 1 đến 9 với mỗi trại từ 20 đến hơn 25 trại sinh. Mỗi tiểu trại như vậy sẽ được phân cho một Tiểu trại trưởng để quản lý và kết nối các trại sinh. Tôi may mắn được đồng hành cùng một bạn nữ Tiểu trại trưởng tuyệt vời.</p>
<p><figure id="attachment_1418" aria-describedby="caption-attachment-1418" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1418" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-211.jpg" alt="Cụm Thanh Tịnh ở buổi thuyết giảng" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-211.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-211-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1418" class="wp-caption-text">Cụm Thanh Tịnh</figcaption></figure></p>
<p>Vì nhà tôi cách trung tâm Thành phố Hồ Chí Minh khá xa nên Tiểu trại trưởng khuyên tôi nên ngủ lại chùa 1 đêm để sáng xuất phát sớm. Đó là một quyết định sáng suốt. Với thời gian xuất phát là 3h sáng, bạn cần một đêm nghỉ ngơi đủ giấc cho chuyến đi xa. Nó cũng sẽ an toàn hơn khi bạn không cần di chuyển trong đêm giữa lòng thành phố.</p>
<p>Ngủ ở chùa tuy có hơi gọi là bất tiện. Nhưng tôi đã hoàn toàn bỏ ngoài hết sự bất tiện đó bởi sự nhiệt tình của các bạn trại sinh khác. Bạn đến sớm trước thời gian đóng cổng của chùa là 22h, bạn sẽ có thời gian giao lưu tuyệt vời cùng những trại sinh khác. Đó có thể là những câu chuyện vui, làm quen cùng nhau. Cũng có thể là những trận ma sói khởi đầu cho 3 ngày tiếp theo.</p>
<p><figure id="attachment_1361" aria-describedby="caption-attachment-1361" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1361" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo154.jpg" alt="Các bạn trại sinh ở chùa Vĩnh Nghiêm" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo154.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo154-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1361" class="wp-caption-text">Các bạn trại sinh ở chùa Vĩnh Nghiêm</figcaption></figure></p>
<p>Có thêm một buổi ngắn tìm hiểu trước sẽ giúp bạn thân thiết với trại sinh khác hơn trong hành trình 3 ngày Hội trại tiếp theo. Hãy đừng khép mình lại, hòa đồng và nói chuyện nhiều hơn. Bạn sẽ được những Tiểu trại trưởng giúp đỡ trong việc kết nối các trại sinh lại với nhau.</p>
<p>Sau khi thức giấc và vệ sinh, tôi lên xe, bắt đầu hành trình từ trung tâm Quận 3, TP. Hồ Chí MInh đến TP. Phan Thiết thuộc tỉnh Bình Thuận. Bắt đầu hành trình Hội trại Tuổi trẻ Phật giáo 2018</p>
<h3>Cứ tham quan du lịch địa phương trước đã</h3>
<p>Điểm đầu tiên tôi cùng tiểu trại của mình đặt chân đến không phải là một ngôi chùa hay một khu đất cấm trại nào đó mà là điểm tham quan du lịch tháp Chăm. Mọi người được tham quan địa điểm di tích văn hóa tuyệt vời này trong một thời gian khoảng 1 tiếng.</p>
<p>Tháp Chăm là điểm di sản văn hóa cấp quốc gia của thành phố Phan Thiết. Tháp có cái tên là&nbsp;Pôshanư. Bạn sẽ được tham quan quần thể di tích tháp Chăm cổ xưa. Đặc biệt, bạn sẽ chiêm ngưỡng điệu nhảy dân tộc của người Chăm ngay tại địa điểm này.</p>
<p><figure id="attachment_1356" aria-describedby="caption-attachment-1356" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1356" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo149.jpg" alt="Trại sinh tham quan tháp chàm" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo149.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo149-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1356" class="wp-caption-text">Trại sinh tham quan tháp chàm</figcaption></figure></p>
<p>Ngoài việc tự sướng một mình, bạn cũng đừng bỏ qua việc chụp chung một tấm ảnh tập thể đầy hào hứng cùng tiểu trại của mình nhé!</p>
<p><figure id="attachment_1358" aria-describedby="caption-attachment-1358" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1358 size-full" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo151.jpg" alt="Lưu niệm cùng tháp Chăm" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo151.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo151-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1358" class="wp-caption-text">Lưu niệm cùng tháp Chăm</figcaption></figure></p>
<h3>Đến chùa Bửu Sơn &#8211; Xinh đẹp lộng lẫy và to lớn</h3>
<p>Chúng tôi tiếp tục hành trình đi bộ tầm 15 phút để đến địa điểm sẽ lưu trú trong 1 ngày 1 đêm là chùa Bửu Sơn. Ngôi chùa có một kiến trúc xinh đẹp và quy mô to lớn vô cùng. Đây là địa điểm nghỉ đầu tiên của&nbsp;Hội trại Tuổi trẻ Phật giáo 2018.</p>
<p><figure id="attachment_1367" aria-describedby="caption-attachment-1367" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1367" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo160.jpg" alt="Con đường lên chùa Bửu Sơn" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo160.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo160-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1367" class="wp-caption-text">Con đường lên chùa Bửu Sơn</figcaption></figure></p>
<p>Chánh điện của ngôi chùa được sơn vàng nhìn rất bắt mắt.</p>
<p><figure id="attachment_1416" aria-describedby="caption-attachment-1416" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1416" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-209.jpg" alt="Trại sinh tuổi trẻ phật giáo ở bửu sơn tự" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-209.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-209-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1416" class="wp-caption-text">Trại sinh tuổi trẻ phật giáo ở Bửu Sơn Tự</figcaption></figure></p>
<p>Chúng tôi nghỉ ngơi ở tại chùa và bắt đầu dùng cơm sau một thời gian dài di chuyển. Sau thời gian ăn trưa, mọi người tập trung ở chánh điện, chuẩn bị cho những tiết mục chính.</p>
<p>Tôi đã có một buổi nghe giảng pháp tuyệt vời. Thời gian dường như trôi đi qua rất nhanh, 30 phút với Đại Đức Thích Trí Chơn giảng về Tuổi Thanh Xuân. Bạn sẽ làm gì, nghĩ gì và nên như thế nào với tuổi thanh xuân của mình.</p>
<p><figure id="attachment_1424" aria-describedby="caption-attachment-1424" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1424" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-217.jpg" alt="Trại sinh Hội trại tuổi trẻ phật giáo nghe Đại Đức Thích Trí Chơn giảng pháp" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-217.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-217-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1424" class="wp-caption-text">Trại sinh Hội trại tuổi trẻ phật giáo nghe Đại Đức Thích Trí Chơn giảng pháp</figcaption></figure></p>
<p>Tôi đã mạnh dạn phát biểu và đưa ra những câu hỏi mà mình thắc mắc với thầy Thích Trí Chơn. Thầy vô cùng gần gũi và dễ mến, và bạn cũng đâu có nhiều cơ hội gặp được người nổi tiếng như thầy. Nên tôi đã tranh thủ mạnh dạn đứng lên.</p>
<p><figure id="attachment_1425" aria-describedby="caption-attachment-1425" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1425" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-218.jpg" alt="Một trại sinh hỏi về phật pháp trong hội trại" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-218.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-218-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1425" class="wp-caption-text">Một trại sinh hỏi về phật pháp trong hội trại</figcaption></figure></p>
<p>Sau thời gian giảng pháp về tuổi thanh xuân. Thì đến lúc tôi lắng lòng mình và bày tỏ tâm hồn thanh xuân của mình qua lá thư gửi yêu thương. Những dòng tâm sự miên man về tuổi trẻ, những lo âu, những ký ức tuổi thơ từng trôi qua và hiện hữu trong tôi được viết ra một cách ẩn danh. Lá thư như một lời tự sự và trút ra trong tôi mọi sự trăn trở bộn bề của tuổi thanh xuân.</p>
<p><figure id="attachment_1215" aria-describedby="caption-attachment-1215" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1215" src="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo8.jpg" alt="Thư gửi yêu thương tuổi thanh xuân" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo8.jpg 920w, https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo8-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1215" class="wp-caption-text">Thư gửi yêu thương tuổi thanh xuân</figcaption></figure></p>
<p>Sau thời gian lắng đọng, sẽ là một cuộc thi về Phật pháp vô cùng thú vị. Tôi được trải nghiệm một phiên bản trò chơi Rung Chuông Chùa hoàn toàn khác lạ. Những câu trả lời A,B,C,D được đưa ra bằng những động tác ngộ nghĩnh dễ thương khác nhau. Bạn phải mang trong mình một kiến thức đầy đủ về Phật giáo và cả kiến thức thường thức để chiến thắng. Tôi đã tinh tế làm theo số đông và đạt được một kết quả khá cao trong cuộc thi của&nbsp;Hội trại Tuổi trẻ Phật giáo 2018.</p>
<p><figure id="attachment_1219" aria-describedby="caption-attachment-1219" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1219" src="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo12.jpg" alt="Thi kiến thức phật giáo" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo12.jpg 920w, https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo12-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1219" class="wp-caption-text">Thi kiến thức phật giáo</figcaption></figure></p>
<p>Tiếp theo sau phần thi Phật giáo là thời gian ăn uống, nghỉ ngơi và vệ sinh cá nhân. Bạn nên nắm chắc thời điểm rảnh rỗi này để nghỉ ngơi lấy lại sức. Nếu tự tin về sức khỏe, bạn cũng có thể nói chuyện nhiều hơn với tiểu trại của mình để làm quen. Tôi đã tranh thủ thời gian làm quen được thêm rất nhiều bạn mới trong lúc này.</p>
<h3>Đêm yêu thương ngập tràn linh thiêng, lắng động và vô cùng long lanh</h3>
<p>Đến buổi tối, sẽ là thời gian đốt hoa đăng cầu nguyện. Đây là hoạt động ý nghĩa nhất mà tôi tham gia. Một lần nữa, các tôi được nghe giảng pháp ngắn về tình yêu thương: bạn bè, người thân, nhất là về cha mẹ. Tất cả như lắng đọng trong tiếng nhạc thiền. Chúng tôi ngồi yên, đưa hoa đăng về trước mặt, cầu nguyện những yêu thương gửi về cha mẹ, người thân của mình.</p>
<p><figure id="attachment_1225" aria-describedby="caption-attachment-1225" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1225" src="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo18.jpg" alt="Hội trại tuổi trẻ phật giáo" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo18.jpg 920w, https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo18-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1225" class="wp-caption-text">Hội Trại Tuổi Trẻ Phật Giáo</figcaption></figure></p>
<p>Sau những giây phút linh thiêng lắng đọng là một màn chào sân vô cùng ý nghĩa của ca sĩ Phương Anh Idol. Tôi bị choáng ngộp với giọng ca đầy nội lực của cô ấy. Đặc biết trong không gian linh thiêng và cơn mưa phùn phất phới như tô điểm thêm sự hùng vĩ của không gian và lắng đọng của thời gian. Những ánh đèn flash, cơn mưa phùn in đậm vào ký ức thanh xuân của tôi trong&nbsp;Hội trại Tuổi trẻ Phật giáo 2018.</p>
<p><figure id="attachment_1226" aria-describedby="caption-attachment-1226" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1226" src="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo19.jpg" alt="Ca sĩ Phương Anh biểu diễn trong đêm yêu thương" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo19.jpg 920w, https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo19-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1226" class="wp-caption-text">Ca sĩ Phương Anh biểu diễn trong đêm yêu thương</figcaption></figure></p>
<p>Tiếp theo là khoảng thời gian trò chuyện cùng nhau. Hai MC đọc những bức thư nói lên tâm sự của các bạn trại sinh. Đó là những bức thư hài hước hoặc đôi khi là vài dòng tâm sự về nỗi trằn trọc của thanh xuân. Hay đó là những bức thư dài, kể về tuổi thanh xuân đặc biệt của một ai đó dấu tên giữa 1000 trại sinh. Tôi đã được trải qua đầy đủ cảm xúc đặc biệt qua giọng đọc truyền cảm của hai MC.</p>
<p><img loading="lazy" decoding="async" class="size-full wp-image-1222" src="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo15.jpg" alt="Hai MC trong đêm yêu thương" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo15.jpg 920w, https://media.huynhhieutravel.com/Hội-trại-tuổi-trẻ-phật-giáo15-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><span style="font-size: 14px;">Hai MC trong đêm yêu thương</span></p>
<p>Kết thúc Đêm Yêu Thương, tôi đã đong đầy bụng thêm nữa bằng một tô chè đầy bự. Tôi và các trại sinh khác đã được đãi một món ăn khuya để lấy sức cho những hành trình tiếp theo.</p>
<p>Sáng hôm sau, chúng tôi đặt chân đến đất trại.</p>
<h3>Buổi sinh hoạt đầu tiên và tôi trổ tài dựng trại</h3>
<p>Buổi sinh hoạt đất trại đầu tiên vô cùng hào hứng. 1000 con người trẻ cùng hòa mình làm một theo những điệu nhạc, bài ca đất trại. Tôi hát những bài ca thông dụng như Nối Vòng Tay Lớn cùng các trại sinh khác đến khản giọng. Tôi vỗ tay theo nhịp, đưa tay lên xuống, rồi cùng choàng vai nhau với những năng lượng tuổi trẻ trong mình.</p>
<p><figure id="attachment_1270" aria-describedby="caption-attachment-1270" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1270 size-full" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo63.jpg" alt="Hội trại tuổi trẻ phật giáo 2018" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo63.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo63-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1270" class="wp-caption-text">Hội trại tuổi trẻ phật giáo 2018</figcaption></figure></p>
<p>Sau buổi sinh hoạt là đến quy trình dựng trại. Chúng tôi bắt tay vào quá trình chuẩn bị cho việc trang trí trại. Mỗi bạn trại lại có những nhiệm vụ khác nhau nhưng lại gắn bó mật thiết cùng nhau. Có những bạn thì leo lên trang trí phần mái lều.</p>
<p><figure id="attachment_1251" aria-describedby="caption-attachment-1251" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1251" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo44.jpg" alt="Leo lên cao dựng lều hội trại tuổi trẻ" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo44.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo44-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1251" class="wp-caption-text">Leo lên cao dựng lều hội trại tuổi trẻ</figcaption></figure></p>
<p>Có những bạn thì tập trung dán chữ lên bảng trại&nbsp;Hội trại Tuổi trẻ Phật giáo 2018.</p>
<p><figure id="attachment_1254" aria-describedby="caption-attachment-1254" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1254" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo47.jpg" alt="Dán bảng trại" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo47.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo47-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1254" class="wp-caption-text">Dán bảng trại</figcaption></figure></p>
<p>Hay có những bạn treo những bức hình của trại sinh lên trang trí cho cả cụm trại. Và việc lao động làm đẹp cho trại khiến chúng tôi trân trọng trại của mình hơn. Lao động thật sự mang lại vinh quang rất nhiều.&nbsp;Hội trại Tuổi trẻ Phật giáo 2018 đã càng khẳng định hơn điều đó.</p>
<p>Tiếp tục đến thời gian cơm trưa và nghỉ ngơi. Chúng tôi bắt đầu với những trò chơi tập thể như gọi tên tất cả trại sinh, nếu ai không thuộc sẽ bị phạt nhẹ. Hoặc những trò chơi tập thể. Những trại khác là những bài ca hát vang lên cùng tiếng vỗ tay. Và cũng có thể cả những tiếng từ loa kẹo kéo phát ra từ những trại kế bên, nhưng vẫn không quá ồn. Tất cả tiếng động như tạo nên một không khí của một kỳ trại náo nhiệt đầy rực lửa của tuổi thanh xuân.</p>
<p><figure id="attachment_1364" aria-describedby="caption-attachment-1364" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1364" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo157.jpg" alt="Các bạn trại sinh vui vẻ chụp hình cùng nhau" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo157.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo157-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1364" class="wp-caption-text">Các bạn trại sinh vui vẻ chụp hình cùng nhau</figcaption></figure></p>
<h3>Tham gia trò chơi nhỏ&nbsp;Hội trại Tuổi trẻ Phật giáo 2018</h3>
<p>Sau thời gian trang trí và sinh hoạt cùng nhau là bắt đầu Trò Chơi Nhỏ của hội trại. Mỗi tiểu trại sẽ bắt đầu chia ra để tham gia những trò chơi khác nhau và thi đua kết quả. Những trạm trò chơi là những trò vô cùng lầy lội. Nó có thể là một đường đua tổng hợp tiếp sức với đoạn đường đầy bột.</p>
<p><figure id="attachment_1384" aria-describedby="caption-attachment-1384" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1384" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo177.jpg" alt="Trại ính tham gia trò chơi nhỏ" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo177.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo177-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1384" class="wp-caption-text">Trại sinh tham gia trò chơi nhỏ</figcaption></figure></p>
<p>Bạn phải nhảy lên để dùng đỉnh nhọn của nón phá vỡ quả bóng. Và không biết bên trong bong bóng có thể là bột hay nước,&#8230;</p>
<p><figure id="attachment_1385" aria-describedby="caption-attachment-1385" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1385" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo178.jpg" alt="Trò chơi nhỏ" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo178.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo178-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1385" class="wp-caption-text">Trò chơi nhỏ</figcaption></figure></p>
<p>Trò chơi cũng có thể là làm vòi voi xoay tròn quanh trụ vài vòng rồi ném cồn qua vòng.</p>
<p><figure id="attachment_1382" aria-describedby="caption-attachment-1382" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1382" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo175.jpg" alt="Trò chơi nhỏ" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo175.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo175-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1382" class="wp-caption-text">Trò chơi nhỏ</figcaption></figure></p>
<p>Hoặc bạn cũng có thể được ngồi lên xe đẩy được kéo đi khắp nơi.</p>
<p><figure id="attachment_1380" aria-describedby="caption-attachment-1380" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1380" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo173.jpg" alt="Một bạn được kéo đi trong trò chơi nhỏ" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo173.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo173-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1380" class="wp-caption-text">Một bạn được kéo đi trong trò chơi nhỏ</figcaption></figure></p>
<p>Đặc biệt mình gọi trò này là lăn bao bố. Mọi người sẽ ở trong bao bố và lăn đến đích. Mọi thứ khi chơi đều thú vị vô cùng. Bạn sẽ được hòa mình cùng tiểu trại với trò chơi này. Tôi thật sự bị kích thích phấn khích khi cùng mọi người chơi game.</p>
<p><figure id="attachment_1369" aria-describedby="caption-attachment-1369" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1369" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo162.jpg" alt="Trò chơi lăn bao bố" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo162.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo162-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1369" class="wp-caption-text">Trò chơi lăn bao bố</figcaption></figure></p>
<h3>Cùng hơn 1000 trại sinh tắm biển</h3>
<p>Sau khoảng thời gian đổ mồi hôi cùng những trò chơi nhỏ với tiểu trại. Tôi hướng ra biển cùng hơn 1000 trại sinh khác. Hè về rồi thì chúng ta phải bắt đầu tắm biển đi thôi. Tôi thật sự bất ngờ vì đến giờ mới biết tắm biển là vui đến vậy.</p>
<p>Chúng tôi xếp thành nhiều kiểu khác nhau để chụp nên những bức ảnh đẹp và độc.</p>
<p><img loading="lazy" decoding="async" class="size-full wp-image-1296" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo89.jpg" alt="Trại sinh xếp hình trái tim" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo89.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo89-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><span style="font-size: 14px;">Trại sinh xếp hình trái tim</span></p>
<p>Tôi và các bạn trại sinh khác xếp hình tháp. Nó thật sự đòi hỏi sự chịu đựng vô cùng mạnh mẽ của cơ thể. Đến giờ tôi mới hiểu sự vĩ đại của chàng trai Hercules khi khuân cả thế giới để lấy trái táo vàng. Tôi không biết cả thế giới nặng bao nhiêu kí nhưng trên vai tôi là vài chàng trai hàng trăm kí. Wow, thật sự khó khăn, nhưng vui vô cùng.</p>
<p><figure id="attachment_1292" aria-describedby="caption-attachment-1292" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1292" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo85.jpg" alt="Trại sinh xây tháp ở biển" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo85.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo85-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1292" class="wp-caption-text">Trại sinh xây tháp ở biển</figcaption></figure></p>
<p>Sau thời gian tắm biển, chúng tôi trẻ về đất trại vệ sinh cá nhân và dùng cơm.</p>
<h3>Đêm văn nghệ tuyệt vời với những màn trình diễn mãn nhãn</h3>
<p>Tôi thật sự bất ngờ với những màn trình diễn tuyệt vời của các trại sinh khác. Đó là những màn võ nhạc đầy hấp dẫn. Những bạn trẻ lồng ghép những động tác võ thuật tuyệt vời mạnh mẽ cùng những điệu nhảy như những thần tượng Kpop tuyệt vời. Bạn sẽ không thể rời mắt khỏi những điệu nhảy võ nhạc đấy.</p>
<p><figure id="attachment_1299" aria-describedby="caption-attachment-1299" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1299" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo92.jpg" alt="Võ nhạc hội trại tuổi trẻ" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo92.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo92-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1299" class="wp-caption-text">Võ nhạc hội trại tuổi trẻ</figcaption></figure></p>
<p>Tất cả cùng vỡ òa hơn khi ca sĩ Phan Duy Anh trong cuộc thi The Voice xuất hiện.</p>
<p><figure id="attachment_1388" aria-describedby="caption-attachment-1388" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1388" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo181.jpg" alt="Ca sĩ Phan Duy Anh" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo181.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo181-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1388" class="wp-caption-text">Ca sĩ Phan Duy Anh</figcaption></figure></p>
<p>Và cả sự xuất hiên của nữ ca sĩ trẻ trung Bảo Uyên tạo nên một không khí vô cùng sôi động.</p>
<p><figure id="attachment_1300" aria-describedby="caption-attachment-1300" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1300 size-full" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo93.jpg" alt="Ca sĩ Bảo Uyên biểu diễn ở hội trại" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo93.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo93-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1300" class="wp-caption-text">Ca sĩ Bảo Uyên biểu diễn ở hội trại</figcaption></figure></p>
<p>Tôi thật sự ấn tượng với đêm nhạc trong buổi tối này</p>
<h3>Đêm lửa trại đầy hoang dại</h3>
<p>Và cuối cùng điều chờ đợi nhất của tôi là đêm lửa trại đã bắt đầu. Lửa trại được thắp sáng lên trong niềm hân hoan.</p>
<p><figure id="attachment_1303" aria-describedby="caption-attachment-1303" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1303" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo96.jpg" alt="Mọi người hân hoan bên lửa trại" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo96.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo96-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1303" class="wp-caption-text">Mọi người hân hoan bên lửa trại</figcaption></figure></p>
<p>Chủ đề trại là Tuổi Thanh Xuân được thắp sáng bởi ngọn lửa của thanh xuân.</p>
<p><figure id="attachment_1304" aria-describedby="caption-attachment-1304" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1304" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo97.jpg" alt="Lửa trại tuổi trẻ phật giáo với chủ đề tuổi thanh xuân" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo97.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo97-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1304" class="wp-caption-text">Lửa trại tuổi trẻ phật giáo với chủ đề tuổi thanh xuân</figcaption></figure></p>
<p>Mọi người quay quần bên những điệu nhạc, những trò chơi được dẫn bởi MC. Mọi thứ mệt nhoài trong cuộc sống như được rũ bỏ tất cả. Bạn sẽ được vui cùng những người trẻ, những bạn luôn hết mình trong ngày Hội trại Tuổi trẻ Phật giáo 2018. Tôi như hòa mình vào cái nóng của lửa trại và sự nhiệt tình cũng những người xung quanh.</p>
<p><figure id="attachment_1306" aria-describedby="caption-attachment-1306" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1306" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo99.jpg" alt="Đêm lửa trại quây quần bên nhau" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo99.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo99-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1306" class="wp-caption-text">Đêm lửa trại quây quần bên nhau</figcaption></figure></p>
<h3>Thiền định và lắng lòng mình ở đất trại Bồng Lai &#8211; Mũi Né</h3>
<p>Sáng hôm sau tôi dậy sớm sau một ngày lửa trại vui tươi nhưng hau hầu hết năng lượng của mình. Tôi bắt đầu thiền tập theo hướng dẫn của Đại đức Thích Thiện Bảo. Thầy dạy chúng tôi cách ngồi đúng tư thế, cách hít vào thở ra như thế nào là đúng. Đặc biệt, tâm chúng ta phải luôn thanh tịnh. Bạn phải thiền đúng cách để đẩy đi những nguồn năng lượng tiêu cực trong cơ thể và phục hồi thể xác, tinh thần trở lại. Tôi dần như trút bỏ hết những sự mệt mỏi những ngày qua, đặc biệt những lo âu trong công việc bản thân như nhẹ gánh đi. Tôi nhận ra thiền định là tốt như thế nào cho cơ thể chúng ta.</p>
<p><figure id="attachment_1391" aria-describedby="caption-attachment-1391" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1391" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo184.jpg" alt="Đại đức Thích Thiện Bảo hướng dẫn trại sinh thiền định ở hội trại tuổi trẻ phật giáo lần thứ 13" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo184.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo184-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1391" class="wp-caption-text">Đại đức Thích Thiện Bảo hướng dẫn trại sinh thiền định ở hội trại tuổi trẻ phật giáo lần thứ 13</figcaption></figure></p>
<p>Sau buổi thiền định, chúng tôi được thầy Thích Thiện Bảo dẫn đầu đi bộ một cách thanh thản và nhẹ nhàng ra biển. Chúng tôi nối đuôi nhau thành những đoàn người dài xếp thành 3 hàng. Bước chân nhẹ nhàng, hít thở thật đều, tâm thanh tịnh. Tôi thiền hành trong một sự thanh thản trong tâm hồn hướng ra biển đón bình minh vừa hé ở Mũi Né.</p>
<p><figure id="attachment_1389" aria-describedby="caption-attachment-1389" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1389" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo182.jpg" alt="Đi bộ đón bình minh ở biển" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo182.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo182-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1389" class="wp-caption-text">Đi bộ đón bình minh ở biển</figcaption></figure></p>
<p>Ánh nắng bình minh nhẹ nhàng không chói chang chíu rọi vào chúng tôi. Nắng làm ấm hơn cơ thể mình, biển sóng nhè nhẹ thổi vào bờ. Tiếng sóng biển dạt dào làm tôi như hòa vào thiên nhiên. Và hòa vào dòng người của&nbsp;Hội trại Tuổi trẻ Phật giáo 2018.</p>
<p><figure id="attachment_1311" aria-describedby="caption-attachment-1311" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1311" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo104.jpg" alt="Trại sinh đón bình minh ở biển" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo104.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo104-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1311" class="wp-caption-text">Trại sinh đón bình minh ở biển</figcaption></figure></p>
<h3>Trò chơi lớn Hội trại Tuổi trẻ Phật giáo 2018</h3>
<p>Trò chơi lớn bao gồm 5 trò chơi khác nhau được xây dựng kiểu team building game. Chúng tôi chia thành 4 cụm trại lớn và hướng đến những trạm trò chơi của Hội trại Tuổi trẻ Phật giáo 2018. Mọi người cần một giấy thông hành và giải những mật thư khó nhằn ở mỗi trạm.</p>
<p><figure id="attachment_1320" aria-describedby="caption-attachment-1320" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1320" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo113.jpg" alt="Phiếu thông hành chơi trò chơi lớn" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo113.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo113-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1320" class="wp-caption-text">Phiếu thông hành chơi trò chơi lớn</figcaption></figure></p>
<p>Những trò chơi đòi hỏi sự kết nối giữa các đồng đội với nhau. Như trò gánh nước, những người đồng đội phải gánh chiếc thúng nước bị lủng sang cầu và làm đầy thau nước. Tôi và các bạn trại sinh đã vất vả và đồng lòng để làm đầy thùng nước đó. Nhưng vui và cảm giác cùng nhau hoàn thành những thứ khó khăn thật tuyệt vời.</p>
<p><figure id="attachment_1405" aria-describedby="caption-attachment-1405" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1405" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo198.jpg" alt="Trại sinh tham gia trò chơi lớn" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo198.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo198-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1405" class="wp-caption-text">Trại sinh tham gia trò chơi lớn</figcaption></figure></p>
<p>Ngoài ra trò chơi vượt cầu phao vô cùng gay cấn. Nó đòi hỏi sự khéo léo và thăng bằng tuyệt vời từ các bạn trại sinh. Nếu không khéo léo qua được thì bạn sẽ bị ướt sủng đấy.</p>
<p><figure id="attachment_1400" aria-describedby="caption-attachment-1400" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1400" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo193.jpg" alt="Trò chơi lớn" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo193.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo193-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1400" class="wp-caption-text">Trò chơi lớn</figcaption></figure></p>
<p>Hay trò chơi đòi hỏi sự khéo léo và đồng đều từ một tập thể như cân bằng thúng. Chúng tôi phải cân bằng chiếc thúng chất đầy vật dụng bên trong. Bạn cần khéo lẹo và dùng mẹo để mang được nó đến đích.</p>
<p><figure id="attachment_1322" aria-describedby="caption-attachment-1322" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1322" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo115.jpg" alt="Các trại sinh họp sức chơi trò chơi lớn" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo115.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo115-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1322" class="wp-caption-text">Các trại sinh họp sức chơi trò chơi lớn</figcaption></figure></p>
<p>Kết thúc trò chơi lớn là một thân xác rã rời. Nhưng tôi thật sự quá vui vì lâu rồi không trải qua những vận động của toàn bộ cơ thể như thế: Từ sự khóe léo, trí tuệ, cơ bắp, thăng bằng và sức bền. Tất cả đòi hỏi cơ thể phải vận động đều tất cả.</p>
<p>Thế là đã kết thúc một kỳ hội trại đầy ý nghĩa. Tôi đã học được nhiều thứ, trải nghiệm được nhiều thứ từ Hội trại Tuổi trẻ Phật giáo 2018 với lần tổ chức thứ 13 này. Nếu đến hè năm sau, bạn hãy thử đăng ký và trải nghiệm nó nhé! Thật sự rất tuyệt vời đấy!</p>
<p>Một số hình ảnh trong Hội trại Tuổi trẻ Phật giáo 2018:</p>
<p><figure id="attachment_1415" aria-describedby="caption-attachment-1415" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1415" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-208.jpg" alt="Mọi người vui vẻ sinh hoạt khóa tu mùa hè" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-208.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo-208-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1415" class="wp-caption-text">Mọi người vui vẻ sinh hoạt khóa tu mùa hè</figcaption></figure></p>
<p><figure id="attachment_1395" aria-describedby="caption-attachment-1395" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1395" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo188.jpg" alt="Tình nguyện viên vui vẻ nhảy cùng nhau" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo188.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo188-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1395" class="wp-caption-text">Tình nguyện viên vui vẻ nhảy cùng nhau</figcaption></figure></p>
<p><figure id="attachment_1349" aria-describedby="caption-attachment-1349" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1349" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo142.jpg" alt="Trại sinh thể hiện sự đoàn kết" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo142.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo142-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1349" class="wp-caption-text">Trại sinh thể hiện sự đoàn kết</figcaption></figure></p>
<p><figure id="attachment_1340" aria-describedby="caption-attachment-1340" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1340" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo133.jpg" alt="Màn tung bột của trại sinh" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo133.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo133-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1340" class="wp-caption-text">Màn tung bột của trại sinh</figcaption></figure></p>
<p><figure id="attachment_1316" aria-describedby="caption-attachment-1316" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1316" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo109.jpg" alt="Giải mật thư của team game" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo109.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo109-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1316" class="wp-caption-text">Giải mật thư của team game</figcaption></figure></p>
<p><figure id="attachment_1295" aria-describedby="caption-attachment-1295" style="width: 920px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1295" src="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo88.jpg" alt="Trại sinh và hình trang trí của mình" width="920" height="613" srcset="https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo88.jpg 920w, https://media.huynhhieutravel.com/Hội-Trại-Tuổi-Trẻ-Phật-Giáo88-768x512.jpg 768w" sizes="(max-width: 920px) 100vw, 920px" /><figcaption id="caption-attachment-1295" class="wp-caption-text">Trại sinh và hình trang trí của mình</figcaption></figure></p>
', 'Hội trại Tuổi trẻ Phật giáo 2018 là một khóa tu tập được diễn ra vào hè tháng 7 trong 3 ngày. Đặc biệt, tôi đã có một trải nghiệm tuyệt vời ở Hội trại Tuổi trẻ Phật giáo năm 2018 với lần tổ chức thứ 13 này. Tôi cùng với hơn 1000 trại sinh [&hellip;]', 1225, 'post', '2018-08-03 05:16:17', '2023-04-23 12:25:50');
