INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1200, 'Herne The Hunter &#8211; Vị chúa tể của rừng', 'herne-the-hunter', '<p>Herne the Hunter là một nhân vật trong truyền thuyết ở Anh. Herne the Hunter là một con ma cư trú tại Windsor Forest và Great Park ở Anh. Trên đầu của <strong>Herne the Hunter</strong> là một đôi gạc của nai và luôn cưỡi một con ngựa. Herne the Hunter xuất hiện từ vở kịch The Merry Wives of Windsor của William Shakespeare vào năm 1597. Đến giờ vẫn chưa thể biết chính xác rằng Shakespeare đã sáng tạo ra nhân vật Herne the Hunter hay đã đưa một phần Herne the Hunter từ trong truyền thuyết địa phương vào vở kịch.</p>
<h3>Herne the Hunter &#8211; Vụ chúa tể của rừng</h3>
<h4>Nguồn gốc ra đời Herne the Hunter</h4>
<p>Chúng ta có rất ít bằng chứng để tìm hiểu về nguồn gốc của Herne the Hunter. Tài liệu sớm nhất tìm thấy được là từ vở kịch của nhà soạn kịch vĩ đại Shakespeare (Tác phẩm nổi bật nhất của ông là Romeo and Juliet). Trong vở kịch The Merry Wives of Windsor (1597) có đoạn:</p>
<p><strong><em>Sometime a keeper here in Windsor Forest,</em></strong></p>
<p><strong><em>Doth all the winter-time, at still midnight,</em></strong></p>
<p><strong><em>Walk round about an oak, with great ragg&#8217;d horns;</em></strong></p>
<p><strong><em>And there he blasts the tree, and takes the cattle,</em></strong></p>
<p><strong><em>And makes milch-kine yield blood, and shakes a chain</em></strong></p>
<p><strong><em>In a most hideous and dreadful manner.</em></strong></p>
<p><strong><em>You have heard of such a spirit, and well you know</em></strong></p>
<p><strong><em>The superstitious idle-headed eld</em></strong></p>
<p><strong><em>Receiv&#8217;d, and did deliver to our age,</em></strong></p>
<p><strong><em>This tale of Herne the Hunter for a truth.</em></strong></p>
<dl>
<dd>&#8211; William Shakespeare, <i>The Merry Wives của Windsor</i></dd>
</dl>
<p><figure id="attachment_1202" aria-describedby="caption-attachment-1202" style="width: 500px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1202" src="https://media.huynhhieutravel.com/Herne-the-Hunter.jpg" alt="Herne the Hunter" width="500" height="337" /><figcaption id="caption-attachment-1202" class="wp-caption-text">Herne the Hunter</figcaption></figure></p>
<p>Sau này vào năm 1602 cũng có một vài phiên bản khác xuất hiện về Herne the Hunter. Nhưng phiên bản này chủ yếu để dọa những đứa trẻ không ngoan. Nó nói về câu chuyện một con ma tàn bạo đi lại lang thang trong rừng với cái tên Herne the Hunter.</p>
<h4>Herne the Hunter trong thần thoại Anh</h4>
<p>Câu chuyện kể về một thợ săn tên Herne làm việc cho vua Richard II. Một thời gian sau có những người ghen tỵ với anh ta. Họ đã vu oan anh ta săn trộm trên mảnh đất của đức vua. Bị vu oan và những người bạn thân thiết ruồng bỏ. Herne đi lang thang khắp khu rừng và tự sát trên một cây sồi.</p>
<p><figure id="attachment_1205" aria-describedby="caption-attachment-1205" style="width: 500px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1205" src="https://media.huynhhieutravel.com/Herne-the-Hunter4.jpg" alt="Herne the Hunter" width="500" height="353" srcset="https://media.huynhhieutravel.com/Herne-the-Hunter4.jpg 1024w, https://media.huynhhieutravel.com/Herne-the-Hunter4-370x260.jpg 370w, https://media.huynhhieutravel.com/Herne-the-Hunter4-768x542.jpg 768w" sizes="(max-width: 500px) 100vw, 500px" /><figcaption id="caption-attachment-1205" class="wp-caption-text">Herne the Hunter</figcaption></figure></p>
<p>Ngoài ra có một số phiên bản khác. Theo đó Herne đã bị thương nặng khi cứu vua Richard II khỏi một vụ tông xe. Anh được một người xa lạ cứu chữa bằng cách lấy gạc của một con nai đã chết gắn vào trán. Nhưng người lạ đã yêu cầu Herne trả công bằng những kỹ năng của mình. Phát điên vì mất đi những kỹ năng mà anh yêu quý. Herne chạy trốn vào rừng, treo cổ tự sát bên một cây sồi. Tuy vậy, mỗi đêm anh vẫn hiện về dẫn đầu cuộc săn đuổi của mình ở Windsor Forest.</p>
<h4>Vì sao Herne the Hunter là chúa tể của rừng?</h4>
<p>Ngoài việc từng là một thợ săn tuyệt vời khi còn sống. Herne the Hunter còn có một đôi gạc sừng tuyệt vời. Theo quan niệm của người xưa ở phương Tây, chiếc sừng đại diện cho quyền lực của những vị thần cổ xưa. Nó thể hiện sự uy nghiêm và một sức mạnh thiên nhiên tuyệt vời.</p>
<p><figure id="attachment_1203" aria-describedby="caption-attachment-1203" style="width: 500px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1203" src="https://media.huynhhieutravel.com/Herne-the-Hunter2.jpg" alt="Herne the Hunter" width="500" height="414" srcset="https://media.huynhhieutravel.com/Herne-the-Hunter2.jpg 1181w, https://media.huynhhieutravel.com/Herne-the-Hunter2-768x637.jpg 768w" sizes="(max-width: 500px) 100vw, 500px" /><figcaption id="caption-attachment-1203" class="wp-caption-text">Herne the Hunter</figcaption></figure></p>
<p>Herne the Hunter xuất hiện với đôi sừng nai, cưỡi trên lưng một con ngựa đen, đem theo một cây cung bằng gỗ. Và đi cùng anh là những con chó săn bay lượn. Truyền thuyết kể lại nếu một ai đi ngang qua con đường của Herne the Hunter thì họ sẽ bị cuốn lấy và đi theo anh ta mãi mãi.</p>
<p>Sự xuất hiện của Herne the Hunter là một điềm xấu cho Hoàng gia. Herne the Hunter chỉ xuất hiện ở khu rừng Windsor Forest khi cần thiết. Và nó luôn là một thời kỳ khủng hoảng của quốc gia.</p>
', 'Herne the Hunter là một nhân vật trong truyền thuyết ở Anh. Herne the Hunter là một con ma cư trú tại Windsor Forest và Great Park ở Anh. Trên đầu của Herne the Hunter là một đôi gạc của nai và luôn cưỡi một con ngựa. Herne the Hunter xuất hiện từ vở kịch The Merry Wives of Windsor của William [&hellip;]', 1204, 'post', '2018-07-18 11:44:36', '2023-04-23 12:33:45');
INSERT OR IGNORE INTO PostCategory (postId, categoryId) VALUES (1200, 431);
INSERT OR IGNORE INTO PostTag (postId, tagId) VALUES (1200, 144);
INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1186, 'Cerberus &#8211; Chú chó canh giữ địa ngục', 'cerberus', '<p>Cerberus là một quái vật trong thần thoại Hy Lạp. Nó là một con chó nhiều đầu bảo vệ cổng của địa ngục. Nó ngăn người chết rời khỏi và chặn những kẻ xâm nhập bất hợp pháp. Cerberus thường được nhắc đến qua câu chuyện của Heracles.</p>
<h3>Cerberus &#8211; Chú chó canh giữ địa ngục</h3>
<p><figure id="attachment_1190" aria-describedby="caption-attachment-1190" style="width: 400px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1190" src="https://media.huynhhieutravel.com/Cerberus2.jpg" alt="Cerberus" width="400" height="225" srcset="https://media.huynhhieutravel.com/Cerberus2.jpg 1280w, https://media.huynhhieutravel.com/Cerberus2-768x432.jpg 768w" sizes="(max-width: 400px) 100vw, 400px" /><figcaption id="caption-attachment-1190" class="wp-caption-text">Cerberus</figcaption></figure></p>
<p>Cerberus được miêu tả khác nhau với nhiều dị bản. Nhưng điều chắc chắn là hinh dạng của nó giống như một con chó.</p>
<h4>Hình dạng của Cerberus</h4>
<p><img loading="lazy" decoding="async" class="alignnone size-full wp-image-1196" src="https://media.huynhhieutravel.com/Cerberus-title.jpg" alt="" width="851" height="200" srcset="https://media.huynhhieutravel.com/Cerberus-title.jpg 851w, https://media.huynhhieutravel.com/Cerberus-title-768x180.jpg 768w" sizes="(max-width: 851px) 100vw, 851px" /></p>
<p>Thường có nhiều tranh cãi về số đầu của Cerberus. Nhưng đa số đều cho rằng nó có 3 đầu. Nó là kết quả của hai quái vật là Echidna và Typhon (Những quái vật sinh ra để hủy diệt Olympus &#8211; Nữa người nữa rắn với thân trên là người). Ngoài ra một số giả thuyết khác cho rằng sở dĩ nó có ba chiếc đầu là vì mỗi chiếc đầu tượng trưng cho quá khứ, hiện tại và tương lai.</p>
<p><figure id="attachment_1191" aria-describedby="caption-attachment-1191" style="width: 400px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1191 size-full" src="https://media.huynhhieutravel.com/Cerberus3.jpg" alt="Cerberus" width="400" height="300" /><figcaption id="caption-attachment-1191" class="wp-caption-text">Cerberus</figcaption></figure></p>
<p>Trong mô tả sớm nhất của Cerberus, Hesiod&#8217;s Theiodony (Khoảng thế kỷ thứ 8 đến thứ 7 TCN), Cerberus có năm mươi đầu. Trong khi Pindar (khoảng năm 522 &#8211; 443 TCN) cho rằng nó có 100 cái đầu. Tuy nhiên, các nhà văn sau này hầu như đều mô tả nó với ba cái đầu.</p>
<p>Trong nghệ thuật, Cerberus thường được mô tả với hai đầu chó, không bao giờ nhiều hơn ba, nhưng đôi khi chỉ có một. Một trong hai mô tả sớm nhất (Khoảng năm 590–580 TCN), một chiếc cốc Corinth từ Argos, nó được thể hiện như một con chó bình thường. Sự xuất hiện đầu tiên của một con Cerberus ba đầu xảy ra ở giữa thế kỷ thứ 6 TCN.</p>
<p>Ngoài ra con nhiều giả thuyết về số đầu hoặc đầu của Cerberus là đầu rắn. Dựa trên giả thuyết cha mẹ của nó đều là những quái vật mình người thân rắn.</p>
<h4>Câu chuyện về Cerberus</h4>
<p><img loading="lazy" decoding="async" class="alignnone size-full wp-image-1197" src="https://media.huynhhieutravel.com/Cerberus-title2.jpg" alt="" width="851" height="200" srcset="https://media.huynhhieutravel.com/Cerberus-title2.jpg 851w, https://media.huynhhieutravel.com/Cerberus-title2-768x180.jpg 768w" sizes="(max-width: 851px) 100vw, 851px" /></p>
<p>Thần thoại duy nhất về Cerberus liên quan đến việc nó bị bắt bởi Heracles. Eurystheus đưa ra nhiệm vụ thứ 12 &#8211; cũng là nhiệm vụ cuối cùng để Heracles thực hiện. Đây là một nhiệm vụ khó khăn mà Eurystheus nghĩ rằng Heracles sẽ không thể thực hiện được.</p>
<p>Hera mớm lời cho Eurystheus: &#8220;Hãy yêu cầu hắn ta xuống địa ngục mà không đem theo bất cứ một thứ vũ khí nào!&#8221;. Tuy nhiên, Hercules đã xin được mang theo bộ da của con sư tử Némée.</p>
<p>Gần đến Địa ngục, Hercules bắt gặp Theseus và Pirithous bị xích vào một tảng đá. Chàng cứu được Theseus nhưng khi định kéo Pirithous lên thì mặt đất rung chuyển dữ dội. Do Pirithious chính là người chủ mưu bắt cóc nàng Persephone &#8211; vợ của Hades.</p>
<p><figure id="attachment_1192" aria-describedby="caption-attachment-1192" style="width: 400px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1192" src="https://media.huynhhieutravel.com/Cerberus4.jpg" alt="Cerberus" width="400" height="400" srcset="https://media.huynhhieutravel.com/Cerberus4.jpg 425w, https://media.huynhhieutravel.com/Cerberus4-150x150.jpg 150w" sizes="(max-width: 400px) 100vw, 400px" /><figcaption id="caption-attachment-1192" class="wp-caption-text">Cerberus mô hình hoạt họa</figcaption></figure></p>
<p>Trở ngại đầu tiên khi muốn xuống địa phủ là phải vượt qua con sông Styx. Nơi những linh hồn của người vừa chết tụ tập chờ đợi để được qua sông trên chiếc thuyền của Charon. Charon sẽ không đưa bất cứ ai qua sông nếu họ chưa hội đủ hai điều kiện sau. Đầu tiên là phải đưa một khoản lộ phí dưới dạng một đồng tiền hình con dê. Hai là người đó đã chết. Hercules không đáp ứng được điều kiện nào. Một trường hợp làm vấn đề thêm trầm trọng với bản tính cáu kỉnh của Charon. Nhưng Hercules chỉ cần vỗ tay là đủ để Charon ngoan ngoãn đưa chàng vượt sông Styx.</p>
<p>Thử thách lớn hơn chính là con Cerberus, với hàm răng sắc nhọn, ba cái đầu, một con rắn độc ở đằng đuôi. Tất cả nhằm vào Hercules khi con nó bất thình lình lao tới chụp vào cổ chàng. May thay, Hercules khoác tấm da con sư tử chàng đã giết trước đây nên không gì có thể xuyên thủng được ngoại trừ sấm sét của Zeus. Hercules cuối cùng cũng quy phục được con Cerberus và lôi nó tới Tiryns. Nơi chàng được tự do sau nhiệm vụ cuối cùng này.</p>
<p>Sau khi tên Eurystheus hoảng sợ năn nỉ chàng đem con chó trở về Địa ngục. Hercules thả con Cerberus trở về. Nó khiếp sợ nhưng cũng rất căm giận nên đã tự tử.</p>
<h4>Biểu tượng Cerberus</h4>
<p>Biểu tượng Cerberus là một biểu tượng thông dụng trong nghệ thuật Hy Lạp và La Mã cổ đại. Những hình tượng này bắt đầu xuất hiện từ thế kỷ thứ 6 TCN. Hình ảnh Cerberus được vẽ lên một chén Corinth (khoảng 590–580 trước Công nguyên). Trên chén Corinth là những hình vẽ kể về hành trình Hercules xuống địa ngục bắt nó.</p>
<p>Đa phần những biểu tượng Cerberus đều là câu chuyện kể về hành trình của Hercules với nhiều biến thể khác nhau. Chúng được khắc trên những bình gốm hay trên mái của một công trình nào đó.</p>
<p>Trong chòm sao Cerberus được giới thiệu bởi Johannes Hevelius năm 1687, nó được vẽ như một con rắn ba đầu, được giữ trong tay Hercules (trước đây những ngôi sao này đã được mô tả như một nhánh cây mọc trên cây Táo của Hesperides).</p>
<p><figure id="attachment_1189" aria-describedby="caption-attachment-1189" style="width: 400px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1189" src="https://media.huynhhieutravel.com/Cerberus.jpg" alt="Cerberus" width="400" height="244" srcset="https://media.huynhhieutravel.com/Cerberus.jpg 1200w, https://media.huynhhieutravel.com/Cerberus-768x468.jpg 768w" sizes="(max-width: 400px) 100vw, 400px" /><figcaption id="caption-attachment-1189" class="wp-caption-text">Hình tượng Cerberus trong Harry Potter</figcaption></figure></p>
<p>Hình tượng Cerberus còn được nhắc đến đến trong Harry Potter với cái tên Fluffy. Nó là con chó canh giữ cổng đường vào căn hầm giữ Hòn đá Phù thủy.</p>
', 'Cerberus là một quái vật trong thần thoại Hy Lạp. Nó là một con chó nhiều đầu bảo vệ cổng của địa ngục. Nó ngăn người chết rời khỏi và chặn những kẻ xâm nhập bất hợp pháp. Cerberus thường được nhắc đến qua câu chuyện của Heracles. Cerberus &#8211; Chú chó canh giữ địa ngục [&hellip;]', 1190, 'post', '2018-07-18 09:33:18', '2023-04-23 12:33:46');
INSERT OR IGNORE INTO PostCategory (postId, categoryId) VALUES (1186, 431);
INSERT OR IGNORE INTO PostTag (postId, tagId) VALUES (1186, 144);
INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1175, 'Banshee &#8211; Nữ thần báo tử', 'banshee', '<p>Banshee hay còn gọi là Nữ thần báo tử là một nhân vật trong thần thoại của <strong><i>Ireland</i></strong>. Người sẽ báo trước cái chết của một thành viên trong gia đình bằng cách khóc lóc hoặc thét lên. Người ta thường cho rằng mỗi gia đình đều có một Banshee cho riêng mình. Thường người ta cho rằng nó xuất hiện với hình dạng một người phụ nữ tóc dài hay khóc về đêm. Cũng có vài giả thuyết cho rằng nó là một nàng tiên hay than khóc.</p>
<h3>Banshee &#8211; Nữ thần báo tử</h3>
<p><figure id="attachment_1176" aria-describedby="caption-attachment-1176" style="width: 500px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1176" src="https://media.huynhhieutravel.com/Banshee.jpg" alt="Banshee" width="500" height="667" srcset="https://media.huynhhieutravel.com/Banshee.jpg 774w, https://media.huynhhieutravel.com/Banshee-768x1024.jpg 768w" sizes="(max-width: 500px) 100vw, 500px" /><figcaption id="caption-attachment-1176" class="wp-caption-text">Banshee</figcaption></figure></p>
<h4>Hình dạng của Banshee</h4>
<p><img loading="lazy" decoding="async" class="alignnone size-full wp-image-1181" src="https://media.huynhhieutravel.com/banshee-title.jpg" alt="" width="851" height="200" srcset="https://media.huynhhieutravel.com/banshee-title.jpg 851w, https://media.huynhhieutravel.com/banshee-title-768x180.jpg 768w" sizes="(max-width: 851px) 100vw, 851px" /></p>
<p>Banshee luôn là một phụ nữ và xuất hiện với nhiều hình dạng khác nhau như:</p>
<ul>
<li>Một người phụ nữ xinh đẹp mặc một bộ đồ liệm người chết.</li>
<li>Một người phụ nữ có bộ mặt nhợt nhạt trong bộ đồ trắng và mái tóc màu đỏ.</li>
<li>Một người phụ nữ mặc một bộ váy màu bạc và mái tóc màu bạc.</li>
<li>Một người phụ nữ không đầu mang theo một bát máu và không mặc áo.</li>
<li>Một người phụ nữ già với đôi mắt màu đỏ, mặc một bộ đồ màu xanh lá và mái tóc màu trắng.</li>
<li>Một người phụ nữ già với mạng che mắt, mặc một bộ đồ màu đen và mái tóc màu trắng.</li>
</ul>
<p>Tác giả Lady Wilde trong <i>Ancient Legends of Ireland</i> đã viết:</p>
<p><em>&#8220;Đôi khi Banshee giả thành những trinh nữ xinh đẹp để báo với thành viên gia đình về cái chết của một ai đó. Hoặc cô ấy có thể được nhìn thấy vào ban đêm như một người phụ nữ, cúi mình dưới gốc cây, than vãn với khuôn mặt bị che khuất. Hoặc bay qua trong ánh trăng, khóc cay đắng. Và tiếng kêu của cô ấy buồn rầu hơn tất cả những âm thanh khác trên trái đất. Nó gây ra cái chết cho một số thành viên của gia đình. Với bất cứ ai nghe thấy nó trong sự im lặng của bóng đêm&#8221;.</em></p>
<p><figure id="attachment_1177" aria-describedby="caption-attachment-1177" style="width: 500px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1177" src="https://media.huynhhieutravel.com/Banshee2.png" alt="Banshee" width="500" height="281" srcset="https://media.huynhhieutravel.com/Banshee2.png 1916w, https://media.huynhhieutravel.com/Banshee2-768x431.png 768w" sizes="(max-width: 500px) 100vw, 500px" /><figcaption id="caption-attachment-1177" class="wp-caption-text">Banshee</figcaption></figure></p>
<p>Lịch sử có chép rằng, năm 1437, vua James I của Scotland (phía bắc vương quốc Anh ngày nay) được một Banshee báo trước về cái chết của ông. Trước khi Bá tước Atholl quyết định làm phản lật đổ ngai vàng, vua James I xứ Scotland đã thoát được vụ ám sát của bá tước Atholl nhờ lời tiên tri ấy.</p>
<h4>Nguồn gốc của Banshee</h4>
<p><img loading="lazy" decoding="async" class="alignnone size-full wp-image-1182" src="https://media.huynhhieutravel.com/banshee-title2.jpg" alt="" width="851" height="200" srcset="https://media.huynhhieutravel.com/banshee-title2.jpg 851w, https://media.huynhhieutravel.com/banshee-title2-768x180.jpg 768w" sizes="(max-width: 851px) 100vw, 851px" /></p>
<p>Các nhà sử học đã truy tìm những câu chuyện đầu tiên của Banshee vào thế kỷ thứ 8. Dựa trên truyền thống về những người phụ nữ hát một bài hát buồn bã để than thở cái chết của ai đó. Những người phụ nữ này được biết đến với tên gọi &#8216;keeners&#8217; và họ chấp nhận rượu như một khoản thanh toán. Họ được cho là tội nhân và bị trừng phạt bằng việc phải chịu đựng số phận trở thành Banshee.</p>
<p><figure id="attachment_1179" aria-describedby="caption-attachment-1179" style="width: 500px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1179" src="https://media.huynhhieutravel.com/Banshee4.jpg" alt="Banshee" width="500" height="500" srcset="https://media.huynhhieutravel.com/Banshee4.jpg 600w, https://media.huynhhieutravel.com/Banshee4-150x150.jpg 150w" sizes="(max-width: 500px) 100vw, 500px" /><figcaption id="caption-attachment-1179" class="wp-caption-text">Banshee</figcaption></figure></p>
<p>Theo thần thoại về Banshee, nếu cô bị phát hiện, cô sẽ biến mất thành một đám mây sương mù. Và hành động này tạo ra một tiếng động tương tự như tiếng chim vỗ cánh. Truyền thuyết nói rằng Banshee không gây ra cái chết; họ chỉ có nhiệm vụ là cảnh báo về cái chết.</p>
<h4>Banshee &#8211; Mặt xấu và tốt</h4>
<p><img loading="lazy" decoding="async" class="alignnone size-full wp-image-1183" src="https://media.huynhhieutravel.com/banshee-title3.jpg" alt="" width="851" height="200" srcset="https://media.huynhhieutravel.com/banshee-title3.jpg 851w, https://media.huynhhieutravel.com/banshee-title3-768x180.jpg 768w" sizes="(max-width: 851px) 100vw, 851px" /></p>
<p><em><strong>Một Banshee tốt</strong></em></p>
<p><figure id="attachment_1180" aria-describedby="caption-attachment-1180" style="width: 500px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1180" src="https://media.huynhhieutravel.com/Banshee5.jpg" alt="Banshee" width="500" height="375" srcset="https://media.huynhhieutravel.com/Banshee5.jpg 1280w, https://media.huynhhieutravel.com/Banshee5-768x576.jpg 768w" sizes="(max-width: 500px) 100vw, 500px" /><figcaption id="caption-attachment-1180" class="wp-caption-text">Banshee</figcaption></figure></p>
<p>Không phải tất cả Banshees đều là những sinh vật đầy đáng ghét. Có một số người có quan hệ chặt chẽ với gia đình họ trong cuộc sống và tiếp tục theo dõi họ sau cái chết. Khi họ thể hiện bản thân, những người Banshee này xuất hiện như một phụ nữ xinh đẹp mê hoặc. Và họ hát một bài hát buồn bã, ám ảnh nhưng đầy những mối quan tâm và tình yêu dành cho gia đình của họ. Bài hát này có thể được hát lên trước một vài ngày để báo một cái chết của một thành viên trong gia đình.</p>
<p><em><strong>Hay một Banshee xấu</strong></em></p>
<p><figure id="attachment_1178" aria-describedby="caption-attachment-1178" style="width: 500px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1178" src="https://media.huynhhieutravel.com/Banshee3.jpg" alt="Banshee" width="500" height="339" /><figcaption id="caption-attachment-1178" class="wp-caption-text">Banshee</figcaption></figure></p>
<p>Ở một mặt xấu khác của Banshee, họ cũng sẽ là những thành viên đã khuất của gia đình. Nhưng bên trong họ mang một nỗi hận hay sự thù ghét nào đó với những thành viên còn lại. Họ thường hay hiện về chọc phá những người trong gia đình. Và khi có một thành viên sắp sửa mất đi, tiếng leng keng của họ không phải là cảnh báo. Mà họ muốn ăn mừng sự sụp đổ của một thành viên đó.</p>
<p>Tuy hiện tại nhiều người cho rằng Banshee là sự hình thành của những sự mê tín dị đoan cổ xưa. Nhưng một phần nào đó nó thể hiện văn hóa yêu thương những người trong gia đình thân thiết với nhau. Những người xưa gây dựng một niềm tin rằng người đã mất vẫn sẽ theo dõi và quan tâm những người còn sống.</p>
', 'Banshee hay còn gọi là Nữ thần báo tử là một nhân vật trong thần thoại của Ireland. Người sẽ báo trước cái chết của một thành viên trong gia đình bằng cách khóc lóc hoặc thét lên. Người ta thường cho rằng mỗi gia đình đều có một Banshee cho riêng mình. Thường người [&hellip;]', 1180, 'post', '2018-07-18 08:12:00', '2023-04-23 12:33:47');
INSERT OR IGNORE INTO PostCategory (postId, categoryId) VALUES (1175, 431);
INSERT OR IGNORE INTO PostTag (postId, tagId) VALUES (1175, 144);
INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1154, 'Black Shuck &#8211; Con chó ma quỷ xui xẻo', 'black-shuck-con-cho-ma-quy-xui-xeo', '<p>Black Shuck hay còn gọi với nhiều cái tên khác như Old Shuck, Old Shock hay đơn giản gọi là Shuck. Những cái tên đó để chỉ một con chó đen ma quỷ đi lang thang khắp các vùng quê xưa ở Anh. Sự xuất hiện của con chó ma Black Shuck như báo hiệu một điềm xui rủi cho người nhìn thấy chúng.</p>
<h3>Black Shuck &#8211; Con chó ma quỷ xui xẻo</h3>
<p><figure id="attachment_1158" aria-describedby="caption-attachment-1158" style="width: 500px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1158" src="https://media.huynhhieutravel.com/Black-Shuck4.jpg" alt="Black Shuck" width="500" height="281" srcset="https://media.huynhhieutravel.com/Black-Shuck4.jpg 1024w, https://media.huynhhieutravel.com/Black-Shuck4-768x432.jpg 768w" sizes="(max-width: 500px) 100vw, 500px" /><figcaption id="caption-attachment-1158" class="wp-caption-text">Black Shuck</figcaption></figure></p>
<p>Black Shuck xuất phát từ tiếng Anh cổ là <i>scucca</i> (Có nghĩa là ma quỷ).</p>
<h4>Đặc điểm của Black Shuck</h4>
<p><figure id="attachment_1156" aria-describedby="caption-attachment-1156" style="width: 313px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1156" src="https://media.huynhhieutravel.com/Black-Shuck2.jpg" alt="Black Shuck" width="313" height="500" /><figcaption id="caption-attachment-1156" class="wp-caption-text">Black Shuck</figcaption></figure></p>
<p>Theo mô tả từ nhiều sách xưa thì Black Shuck có hình dáng như một con chó và có kích thước của một con bê hoặc ngựa. Nó là một con chó màu đen to lớn, có bộ lông xù và đôi mắt to. Một số văn bản biến thể ghi nhận đôi khi Black Shuck chỉ có một con mắt duy nhất ở trán. Nhà văn WA Dutt đã viết trong tác phẩm <strong><i>Highways &amp; Byways in East Anglia</i></strong> xuất bản năm 1901 như sau:</p>
<p><em>Anh ta mang hình dạng của một con chó đen khổng lồ. Và đi dạo dọc theo những con đường tối, những con đường đi bộ ở trường. Nơi mà chỉ với tiếng hú của anh ta cũng khiến máu của người nghe lạnh đi. Nhưng tiếng chân của anh ta không có âm thanh. Bạn đôi lúc có thể nhận thấy anh ta bởi đôi mắt bốc lửa như Cyclops. Nhưng cuộc gặp gỡ như vậy có thể mang lại cho bạn điều xui xẻo nhất, nó có thể là cái chết được báo trước vào cuối năm đó. Vì vậy, bạn tốt nhất là nên nhắm mắt lại khi nghe một tiếng hú. Tuy có thể đó chỉ là tiếng hú của một con chó hoang hay một trò đùa, nhưng hãy cứ thật cẩn thận.</em></p>
<p><figure id="attachment_1159" aria-describedby="caption-attachment-1159" style="width: 500px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1159" src="https://media.huynhhieutravel.com/Black-Shuck5.jpg" alt="Black Shuck" width="500" height="339" /><figcaption id="caption-attachment-1159" class="wp-caption-text">Black Shuck</figcaption></figure></p>
<p>Nhưng không phải những câu chuyện về Black Shuck đều là xấu. Thỉnh thoảng vẫn có những câu chuyện tốt về nó. Đôi khi nó giúp những người chết đuối, hay bảo vệ một địa điểm linh thiêng nào đó.</p>
<p>Black Shuck hình thành và phổ biến nhờ văn hóa tránh cho trẻ em đi khỏi nhà vào những lúc trời tối. Hoặc có câu chuyện nói về những kẻ buôn lậu ở nông thôn tránh những ánh mắt tò mò của người dân.</p>
<h4>Những câu chuyện về Black Shuck</h4>
<p><img loading="lazy" decoding="async" class="size-full wp-image-1161" src="https://media.huynhhieutravel.com/Black-Shuck.jpg" alt="Black Shuck" width="500" height="375" /></p>
<p>Một bài báo về Black Shuck<strong>Nhà thờ Bungay và Blythburgh</strong></p>
<p>Một trong những báo cáo đáng chú ý nhất của Black Shuck là sự xuất hiện của nó tại các nhà thờ của Bungay và Blythburgh ở Suffolk. Vào ngày 4 tháng 8 năm 1577, tại Blythburgh, Black Shuck được cho là đã nổ tung một cánh cửa của Nhà thờ Holy Trinity bằng một tiếng hú như sấm. Nó chạy lên cái hang, băng qua một hội thánh lớn. Nó giết chết một người đàn ông và một cậu bé. Và làm cho gác chuông của nhà thờ sụp đổ. Khi Black Shuck rời đi, nó để lại những vết cháy trên cánh cửa phía bắc được lưu giữ ở nhà thờ cho đến ngày nay.</p>
<p><strong>Tu viện Leiston</strong></p>
<p>Vào tháng 5 năm 2014, xương một con chó lớn được khai quật tại Tu viện Leiston và được liên kết với truyền thuyết về Black Shuck trên báo chí. Kết cấu của xương chỉ ra niên đại của nó khoảng 1650-1690 hoặc 1730-1810 hoặc vào năm 1920.</p>
<p><figure id="attachment_1157" aria-describedby="caption-attachment-1157" style="width: 500px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1157" src="https://media.huynhhieutravel.com/Black-Shuck3.jpg" alt="Black Shuck" width="500" height="302" /><figcaption id="caption-attachment-1157" class="wp-caption-text">Bộ xương được cho là Black Shuck</figcaption></figure></p>
<h4>Sự phổ biến của Black Shuck</h4>
<p>Ngày nay ta có thể bắt gặp nhiều trang sức mang tính thời trang về Black Shuck như một loại vòng tay phổ biến ở Bungay’s (Một thị trấn ở Anh). Ngoài ra ta còn có thể bắt gặp một câu lạc bộ Black Dog Running, một cửa hàng đồ cổ mang tên Black Dog và có cả một đội bóng mang tên &#8216;The Black Dog&#8217;.</p>
<p>Một ban nhạc Rock của anh là The Darkness đã lấy cảm hứng Black Shuck cho album đầu tay của họ là Permission To Land.</p>
<p><figure id="attachment_1160" aria-describedby="caption-attachment-1160" style="width: 500px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1160" src="https://media.huynhhieutravel.com/Black-Shuck6.png" alt="Black Shuck" width="500" height="280" srcset="https://media.huynhhieutravel.com/Black-Shuck6.png 948w, https://media.huynhhieutravel.com/Black-Shuck6-768x429.png 768w" sizes="(max-width: 500px) 100vw, 500px" /><figcaption id="caption-attachment-1160" class="wp-caption-text">Hình tượng cho là của Black Shuck trong Harry Potter</figcaption></figure></p>
<p>Một số dẫn chứng cũng cho rằng câu chuyện trong Harry Potter bắt gặp con chó lang thang màu đen. Và sau này phát hiện ra chính là Sirius trong phần <em><strong>Harry Potter và tên tù nhân ngục Azkaban</strong></em> lấy cảm hứng từ câu chuyện Black Shuck.</p>
', 'Black Shuck hay còn gọi với nhiều cái tên khác như Old Shuck, Old Shock hay đơn giản gọi là Shuck. Những cái tên đó để chỉ một con chó đen ma quỷ đi lang thang khắp các vùng quê xưa ở Anh. Sự xuất hiện của con chó ma Black Shuck như báo hiệu [&hellip;]', 1159, 'post', '2018-07-18 04:22:17', '2023-04-23 12:33:48');
INSERT OR IGNORE INTO PostCategory (postId, categoryId) VALUES (1154, 431);
INSERT OR IGNORE INTO PostTag (postId, tagId) VALUES (1154, 144);
INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1146, 'Basilisk &#8211; Vua của loài rắn', 'basilisk-vua-cua-loai-ran', '<p>Basilisk là một quái vật bò sát huyền thoại. Một vị vua rắn có thể gây ra cái chết chỉ với một ánh nhìn. Trong một số tài liệu miêu tả nó là một con rắn nhỏ không dài quá mười hai ngón tay. Nọc của nó vô cùng độc, cả ánh mắt của nó cũng rất độc. Điểm yếu của nó là mùi của chồn.</p>
<h3>Basilisk &#8211; Vua của loài rắn</h3>
<p><strong>Basilisk</strong> được cho là lấy cảm hứng từ loài hổ mang của châu Á.</p>
<h4>Đặc điểm của Basilisk</h4>
<p>Basilisk được gọi là vua của loài rắn là vì trên đầu của nó luôn có một cái mũ hoặc một vương miện. Nó được phân biệt bởi Cockatrice tuy có xuất xứ gần giống. Nó được nở từ trứng của một con rắn (hoặc cóc) nhưng được ấp bởi một con gà trống.</p>
<p><em>Cockatrice ngược lại với Basilisk, nó được nở từ trứng của một con gà nhưng được ấp bởi một con rắn (hoặc cóc).</em></p>
<p>Một trong những tài liệu đầu tiên nói về Basilisk là cuốn Lịch Sử Tự Nhiên của Pliny the Elder vào khoảng năm 79. Nó được miêu tả: Có một con rắn được gọi là Basilisk. Nó xuất xứ từ tỉnh Cyrene và không dài quá 12 đốt ngón tay.  Nó có một đốm trắng trên đầu. Nó phá hủy tất cả các loại cây xung quanh không những vì thân thể tiếp xúc với chúng mà vì hơi thở của nó. Nó đã đốt cháy tất cả cây cối bằng hơi thở của mình. Nó có thể phá hủy cả đá bằng độc của mình.</p>
<p><figure id="attachment_1149" aria-describedby="caption-attachment-1149" style="width: 367px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1149" src="https://media.huynhhieutravel.com/Basilisk2.png" alt="Basilisk" width="367" height="367" srcset="https://media.huynhhieutravel.com/Basilisk2.png 367w, https://media.huynhhieutravel.com/Basilisk2-150x150.png 150w" sizes="(max-width: 367px) 100vw, 367px" /><figcaption id="caption-attachment-1149" class="wp-caption-text">Basilisk</figcaption></figure></p>
<p>Nếu một chiến binh thử giết chết loại động vật này. Chúng ta có quyền tin rằng không chỉ cây giáo hay gươm của anh ta sẽ bị tan chảy mà cả con ngựa và anh ta cũng sẽ bị tan chảy ra. Với con quái vật mạnh mẽ này, mùi của chồn lại là điểm yếu của nó. Thiên nhiên không có gì là không có thuốc giải độc cho nó. Con chồn sẽ được ném vào hang ổ của nó. Chồn sẽ phá hủy Basilisk bằng mùi của nó, nhưng con chồn cùng sẽ chết trong cuộc chiến của mình.</p>
<div id="js_1q" class="_5pbx userContent _3576" data-ft="{&quot;tn&quot;:&quot;K&quot;}">
<p>Người ta còn tin rằng có thể dùng những chiếc gương để giết nó, khi con quái vật này tự nhìn vào gương và nhìn thấy hình ảnh phản chiếu của mình trong đó, nó sẽ chết vì sợ hãi.</p>
<p><figure id="attachment_1150" aria-describedby="caption-attachment-1150" style="width: 900px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1150" src="https://media.huynhhieutravel.com/Basilisk3.jpg" alt="Basilisk" width="900" height="808" srcset="https://media.huynhhieutravel.com/Basilisk3.jpg 943w, https://media.huynhhieutravel.com/Basilisk3-768x690.jpg 768w" sizes="(max-width: 900px) 100vw, 900px" /><figcaption id="caption-attachment-1150" class="wp-caption-text">Basilisk</figcaption></figure></p>
<p>Một số truyền thuyết cũng nói rằng máu của nó tạo thành một hợp chất chuyển đồng thành vàng.</p>
</div>
<h4>Tài liệu văn học về Basilisk</h4>
<p>Mặc dù là một sinh vật nguy hiểm và mang ý nghĩa chết chóc nhưng nó lại được người dân thành phố Basel &#8211; Thụy Sĩ chọn làm người giám hộ và biểu tượng truyền thống của thành phố này.</p>
<p><figure id="attachment_1152" aria-describedby="caption-attachment-1152" style="width: 900px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1152" src="https://media.huynhhieutravel.com/Basilisk5.jpg" alt="Basilisk" width="900" height="935" srcset="https://media.huynhhieutravel.com/Basilisk5.jpg 2640w, https://media.huynhhieutravel.com/Basilisk5-768x798.jpg 768w" sizes="(max-width: 900px) 100vw, 900px" /><figcaption id="caption-attachment-1152" class="wp-caption-text">Tượng Basilisk ở Basel</figcaption></figure></p>
<p>Basilisk xuất hiện trong bản Kinh Thánh sửa đổi tiếng Anh trong <b>Isaiah</b> 14:29: &#8220;Hân hoan không, O Philistia, tất cả các ngươi, bởi vì thanh hút mùi bị hỏng: và cái rể cây sẽ đưa ra một con Basilisk, và trái cây của nó sẽ là một con rắn bay đang bốc lửa.&#8221;</p>
<p>Trong tác phẩm Richard III của William Shakespeare, quả phụ Anne Nevill sau khi nghe những lời khen ngợi quyến rũ của đôi mắt cô, từ kẻ sát nhân của chồng mình (Richard, Công tước Gloucester). Cô đã trả lời rằng cô ước đôi mắt mình giống như nó, có khả năng nhìn chết hắn ta.</p>
<p><figure id="attachment_1151" aria-describedby="caption-attachment-1151" style="width: 900px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1151" src="https://media.huynhhieutravel.com/Basilisk4.jpg" alt="Basilisk" width="900" height="487" srcset="https://media.huynhhieutravel.com/Basilisk4.jpg 1477w, https://media.huynhhieutravel.com/Basilisk4-768x416.jpg 768w" sizes="(max-width: 900px) 100vw, 900px" /><figcaption id="caption-attachment-1151" class="wp-caption-text">Basilisk trong phim Harry Potter</figcaption></figure></p>
<p>Sự xuất hiện của trong Harry Potter và Phòng chứa Bí mật của JK Rowling cũng là một trích đoạn nổi tiếng: &#8220;Ánh sáng lướt qua một làn da rắn khổng lồ, một màu xanh lá cây , sống động, nằm cuộn tròn và trống rỗng trên sàn hầm. Sinh vật đã đổ nó phải dài ít nhất hai mươi feet&#8221;.</p>
', 'Basilisk là một quái vật bò sát huyền thoại. Một vị vua rắn có thể gây ra cái chết chỉ với một ánh nhìn. Trong một số tài liệu miêu tả nó là một con rắn nhỏ không dài quá mười hai ngón tay. Nọc của nó vô cùng độc, cả ánh mắt của nó cũng [&hellip;]', 1148, 'post', '2018-07-17 14:39:44', '2023-04-23 12:33:49');
INSERT OR IGNORE INTO PostCategory (postId, categoryId) VALUES (1146, 431);
INSERT OR IGNORE INTO PostTag (postId, tagId) VALUES (1146, 144);
INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1139, 'Kelpie &#8211; Ngựa nước ăn thịt người', 'kelpie-ngua-nuoc-an-thit-nguoi', '<p>Kelpie là một loài ngựa nước đến từ sông hồ vùng Scotland. Hình dạng bên ngoài của nó là một con ngựa màu trắng. Nhưng đôi khi nó cũng xuất hiện với hình dạng một cô gái trẻ xinh đẹp. Nó thường dùng hình dạng bên ngoài rực rỡ để lừa người khác theo nó và bắt ăn thịt.</p>
<h3>Kelpie &#8211; Ngựa nước ăn thịt người</h3>
<p><figure id="attachment_1143" aria-describedby="caption-attachment-1143" style="width: 400px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1143" src="https://media.huynhhieutravel.com/Kelpies4.png" alt="Kelpie" width="400" height="320" srcset="https://media.huynhhieutravel.com/Kelpies4.png 900w, https://media.huynhhieutravel.com/Kelpies4-768x614.png 768w" sizes="(max-width: 400px) 100vw, 400px" /><figcaption id="caption-attachment-1143" class="wp-caption-text">Kelpie</figcaption></figure></p>
<p>Hầu hết các vùng địa lý gần nguồn nước ở Scotland đều có một truyền thuyết dị bản về <strong>Kelpie</strong>. Thỉnh thoảng một số câu chuyện cho rằng quái vật hồ Loch Ness chính là một con Kelpie. Nguồn gốc của nó được cho rằng hình thành từ niềm tin của con người với thần linh. Họ muốn xoa diệu các vị thần linh bằng sự hy sinh của mình. Ngoài ra, câu chuyện về nó để cảnh báo những đứa trẻ tránh xa những vùng sông hồ nguy hiểm. Hay cảnh báo phụ nữ và trẻ em cảnh giác với những người lạ mặt.</p>
<h4>Mô tả và thuộc tính phổ biến</h4>
<p>Douglas Harper (Nhà sử học và là người sáng lập từ điển trực tuyến Etymology) định nghĩa Kelpie là một con quái vật mang hình dạng của một con ngựa. Nhưng trong văn hóa của Scotland, nhiều Kelpie với các dị bản khác nhau. Ngoài ra, chúng còn được sử dụng với nhiều cái tên khác nhau ở mỗi vùng. Một số nhà bình luận cũng cho rằng nó không sống hẳn bên trong nước như cá. Mà nó chỉ sống cạnh các bờ sông, suối.</p>
<p>Một số câu chuyện dân gian ở Scotland miêu tả Kelpie là một con ngựa có khả năng kéo dài cơ thể để mang nhiều người cùng một lúc vào vùng nước sâu. Câu chuyện phổ biến vẫn là chúng dụ dỗ trẻ em ở trên bờ và mang chúng vào vùng nước sâu để ăn thịt. Chúng có một chất keo đặc biệt khiến người khác bị dính vào khi chạm đến. Một số biến thể có kể lại câu chuyện một chàng trai phải chặt đứt các ngón tay của mình để trốn khỏi nó. Anh ta trốn thoát được nhưng những đứa trẻ khác chết đuối và bị ăn thịt.</p>
<p>Kelpie cũng được miêu tả có thể sử dụng sức mạnh ma thuật của mình để triệu hồi lũ lụt cuốn người đi. Âm thanh của cái đuôi của nó đi vào nước được cho là giống như tiếng sấm. Và nếu bạn đang đi ngang qua một con sông và nghe thấy một tiếng khóc lóc xao xuyến hoặc hú. Hãy cẩn thận, nó có thể là một lời cảnh báo của nó.</p>
<h4>Sự biến hình</h4>
<p>Kelpie được cho rằng có khả năng biến đổi ngoại hình của chúng thành hình dạng con người. Chúng ta chỉ có thể phân biệt được nó qua dấu hiệu cỏ dại mọc ở trong tóc của chúng. Một số câu chuyện kể về một Kelpie biến thành một phụ nữ xinh đẹp để dụ dỗ những người đàn ông xuống bờ suối. Cô gái áp đảo người đàn ông khỏe mạnh về sức khỏe và kéo xuống bờ suối để ăn thịt. Đôi khi nó cũng biến thành một chàng trai, một ông già để dụ dỗ người khác.</p>
<p><figure id="attachment_1144" aria-describedby="caption-attachment-1144" style="width: 400px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1144" src="https://media.huynhhieutravel.com/Kelpies5.jpg" alt="Kelpie" width="400" height="286" /><figcaption id="caption-attachment-1144" class="wp-caption-text">Kelpie</figcaption></figure></p>
<p>Một câu chuyện dân gian Barra kể về một con Kelpie cô đơn. Nó biến thành một chàng trai trẻ để cưới một cô gái xinh đẹp. Nhưng cô gái đã nhận ra nó vì cỏ dại mọc ở trong tóc anh ta. Cô gái đã bỏ dây chuyền của chàng trai ra (Dây cương của Kelpie) và lập tức chàng trai biến hình trở lại thành Kelpie. Cô gái đem nó về trang trại của mình và bắt nó làm việc trong một năm ở dó.</p>
<p>Sau đó cô gái đã hỏi ý kiến của một người đàn ông thông thái, người bảo cô trả lại chiếc dây chuyền cho Kelpie. Người đàn ông thông thái đã hỏi nó nếu được quay lại lần đầu tiên gặp mặt cô gái. Nó sẽ lựa chọn ăn thịt cô gái hay vẫn tiếp tục cưới cô gái? Nó đã chọn cưới cô gái. Nó đã hỏi lại cô gái là nếu nó là một người đàn ông, cô gái có muốn cưới nó làm vợ hay không? Cô gái đã trả lời là có.</p>
<h4>Điểm yếu của Kelpie</h4>
<p>Kelpie có thể bị khống chế bởi một dấu đóng thánh giá khi xuất hiện dưới hình dạng một con ngựa. Sức mạnh của nó được người xưa sử dụng trong việc vận chuyển đá nặng. Một số câu chuyện dân gian kể rằng địa chủ Morphie đã bắt nó về làm việc cho mình. Nhưng nó đã tức giận về sự lừa đảo của Morphie, sau đó nó để lại một lời nguyền khi hoàn thành công việc. Từ đó nhà Morphie trở nên lụng bại dần.</p>
<p>Giống như người Sói trong phim ảnh, bạn có thể dụng vật dụng bằng bạc như mũi tên hay đạn bằng bạc để tiêu diệt một Kelpie.</p>
<h4>Tác phẩm nghệ thuật về Kelpie</h4>
<p>Những viên đá tượng hình có niên đại từ thế kỷ thứ 6 đến thế kỷ thứ 9 là những biểu tượng về một sinh vật Kelpie hoặc một thứ giống đại loại thế sớm nhất. Những mô tả khác cho thấy nó như những thiếu nữ bên hồ bơi, như trong bức tranh sơn dầu năm 1913 của Draper .Thomas Millie Dow cũng phác hoạ Kelpie năm 1895 với tư cách một thiếu nữ tóc đen u sầu.</p>
<p><figure id="attachment_1141" aria-describedby="caption-attachment-1141" style="width: 400px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1141" src="https://media.huynhhieutravel.com/Kelpies2.jpg" alt="Kelpie" width="400" height="267" srcset="https://media.huynhhieutravel.com/Kelpies2.jpg 790w, https://media.huynhhieutravel.com/Kelpies2-768x512.jpg 768w" sizes="(max-width: 400px) 100vw, 400px" /><figcaption id="caption-attachment-1141" class="wp-caption-text">Kelpie</figcaption></figure></p>
<p>Hai tác phẩm điêu khắc bằng thép cao 30 mét (98ft) ở Falkirk trên kênh Forth và Clyde, có tên The Kelpies. Nó được thiết kế bởi nhà điêu khắc Andy Scott, chúng được xây dựng làm tượng đài cho nền công nghiệp ngựa của Scotland. Công trình xây dựng được hoàn thành vào tháng 10 năm 2013 và các tác phẩm điêu khắc đã được khai trương để tham quan từ tháng 4 năm 2014.</p>
<p><figure id="attachment_1140" aria-describedby="caption-attachment-1140" style="width: 400px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-1140" src="https://media.huynhhieutravel.com/Kelpies.jpg" alt="Tượng đài Kelpie" width="400" height="300" /><figcaption id="caption-attachment-1140" class="wp-caption-text">Kelpie</figcaption></figure></p>
', 'Kelpie là một loài ngựa nước đến từ sông hồ vùng Scotland. Hình dạng bên ngoài của nó là một con ngựa màu trắng. Nhưng đôi khi nó cũng xuất hiện với hình dạng một cô gái trẻ xinh đẹp. Nó thường dùng hình dạng bên ngoài rực rỡ để lừa người khác theo nó [&hellip;]', 1142, 'post', '2018-07-17 12:26:37', '2023-04-23 12:33:51');
