INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1001, 'An Dương Vương Và Nhà Nước Âu Lạc', 'an-duong-vuong', '<p><strong>An Dương Vương</strong> tên thật là Thục Phán. Ông là vị vua duy nhất của triều đại Âu Lạc. Niên đại trị vì của An Dương Vương theo nhiều sử sách ghi lại là khác nhau. Trong Đại Việt Sử Kỳ Toàn Thư cho rằng thời gian ông làm vua kéo dài trong 50 năm từ năm 257 TCN đến 208 TCN. Trong Sử Ký Tư Mã Thiên lại cho rằng ông làm vua từ 208 TCN đến năm 179 TCN trong 30 năm. Những nghiên cứu này đều có sự sai lệch nhất định. Nhưng ta chắc chắn rằng thời kỳ Âu Lạc và An Dương Vương là có thật. Nó hiện diện rõ ràng trong những di tích và sách lịch sử ghi nhận lại. Không hoàn toàn là truyền thuyết như thời Hùng Vương.</p>
<h2>An Dương Vương</h2>
<p><figure id="attachment_1002" aria-describedby="caption-attachment-1002" style="width: 300px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="wp-image-1002" src="https://media.huynhhieutravel.com/an-duong-vuong.jpg" alt="an dương vương" width="300" height="400"><figcaption id="caption-attachment-1002" class="wp-caption-text">Tượng An Dương Vương</figcaption></figure></p>
<h3>Nguồn gốc của Âu Lạc</h3>
<p>Trong thời kỳ Lạc Việt của Hùng Vương, có các bộ tôc gọi là Âu Việt. Họ sống xen kẻ cùng người Lạc Việt. Hai bộ tộc đã sống chung từ lâu đời và gần gũi nhau. Sau này khi An Dương Vương lên làm vua đã đổi quốc hiệu thành Âu Lạc.</p>
<h3>Nghi vấn về sự hình thành của Âu Lạc &#8211; Kẻ xâm lược hay sự đồng hóa?</h3>
<p>Sự hình thành của Âu Lạc được đặt dưới sự nghi ngờ và nhiều giả thuyết khác nhau. Âu Lạc đã xâm chiếm Lạc Việt hay là sau những biến cố lịch sử. Đất nước Lạc Việt đã bị Âu Lạc đồng hóa dần?</p>
<h4>Nghi vấn về nguồn gốc của Thục Phán</h4>
<p>Nguồn gốc của Thục Phán, tức An Dương Vương cũng có nhiều tranh cãi. Một số nhà sử học đã cho rằng Thục Phán là hậu duệ của Trung Quốc. Thời nhà Tần thống nhất các quốc gia. Thục Phán là hậu duệ của nhà Thục đã chạy thoát và xuôi Nam. Hình thành nên Âu Việt và sống xen kẻ cùng tộc Lạc Việt.</p>
<p>Tuy nhiên giả thuyết này bị nghi ngờ về độ chính xác. Xét về mặt không gian, từ đất Thục lúc bấy giờ đến miền Bắc Việt Nam cách xa đến 3000km. Và nên nhớ, lúc bấy giờ &#8220;rừng thiêng nước độc&#8221; và những ngọn đồi cao là cản lực rất lớn. Khó có thể di dân 3000km để thành lập nên bộ tộc. Xét về mặt thời gian, An Dương Vương lên ngôi khoảng 200 đến 250 TCN. Nước Thục bị diệt là vào năm 316 TCN. Nên khó có thể Thục Phán &#8211; An Dương Vương là hậu duệ nhà Thục.</p>
<p><strong>Thuyết nước Nam Cương và người Tày Cao Bằng</strong></p>
<p>Thuyết này lấy căn cứ chủ yếu là truyền thuyết “Chín chúa tranh vua” của đồng bào Tày ở Cao Bằng. Truyền thuyết này đã được Rômanê đuy Caiô nêu từ năm 1880, nhưng trong tay chúng ta không còn tài liệu đó của học giả người Pháp này. Câu chuyện được Lã Văn Lô dịch thành thơ tiếng Việt đăng lại trên tạp chí Nghiên cứu Lịch sử số 50 và số 51 năm 1963 . Đây là tài liệu thu thập được của Sở Văn hóa Việt Bắc.</p>
<p>Từ khi truyền thuyết được công bố, một số người nghiên cứu đã hướng về Cao Bằng để tìm quê hương vua Thục. Truyền thuyết áo lông chim của người Tày – Nùng, tục thờ rùa, truyền thuyết rùa dạy làm nhà, phù hộ người, chống ma quỷ của người Tày – Thái. Một vài địa danh tiếng Tày bắt gặp ở khu gần Cổ Loa như làng Viềng (tức Thành) càng tiếp sức cho thuyết vua Thục vốn người Tày làm chúa nước Nam Cương. Mà trung tâm là huyện Hòa An, tỉnh Cao Bằng ngày nay.</p>
<p>Tới nay, vẫn có người tiếp tục đi sâu nghiên cứu. Và suy đoán rằng tộc đảng Thục Vương đó đã định cư miền gần phía nam Tả Giang, lưu vực Hữu Giang cùng miền thượng lưu các sông Lô, sông Gâm, sông Cầu.</p>
<p>Sau cuộc điều tra ở Cao Bằng hồi tháng 7 và 8 năm 1969, các đồng chí Đỗ Đình Truật và Phạm Như Hồ, viện Khảo cổ học, đã cung cấp những tư liệu có phần khác. Người sưu tầm và viết lại truyền thuyết này là ông Lê Bỉnh Sư (còn có tên là Lê Đình Sự). Người Kinh vốn ở Nghĩa Lộ, sau năm 1947 mới dời về ở tại huyện Hòa An (Cao Bằng). Chính ông Lê Bỉnh Sư kể lại rằng chuyện do ông sắp xếp lại, có sửa ít nhiều cho các chi tiết được hợp lý. Gốc chuyện là do ông chú ngày trước kể, nay nhớ lại mà viết để dự cuộc thi văn nghệ do Sở Văn hóa Việt Bắc tổ chức.</p>
<p>Câu chuyện của truyền thuyết dân gian là những phần nào. Và chi tiết nào là thuộc phần sửa chữa của ông Sư? Chưa có chi tiết để làm sáng tỏ. Đỗ Đình Truật và Phạm Như Hồ đã tìm gặp một số cụ già địa phương để xác minh truyền thuyết. Nhưng không một ai biết chút nào. Vấn đề còn ở tình trạng chưa được sáng tỏ. Như vậy, truyền thuyết này không thể đã được coi là căn cứ đáng tin cho một kết luận khoa học. Và công việc phải tiến hành tức là tiếp tục điều tra lại để xác minh truyền thuyết.</p>
<p><strong>Thuyết Ai Lao Di</strong></p>
<p>Tác giả đã căn cứ vào truyền thuyết Sơn Tinh – Thủy Tinh, nghiên cứu một khối lượng khá lớn thần phả, ngọc phả, tục hèm có liên quan. Thấy rằng Sơn Tinh (tức Thánh Tản viên) là một nhân thần, là người đã có công giúp vua Hùng đánh Thục trong cuộc chiến tranh chống Thục. Đã “được phản ánh một cách rất đậm nét, rất cụ thể trong những truyền thuyết về thời Hùng Vương”. Và “giặc Thục ở đây còn được gọi là giặc Ai Lao, Thục Phán đã từ Ai Lao đến xâm lược Văn Lang”.</p>
<p>Từ truyền thuyết đối chiếu qua thư tịch, đặc biệt Nam Man Tây Nam di truyện trong bộ Hậu hán thư và Thuật dị ký. Tác giả đã tìm ra Tây Thục tức Ai Lao Di, tức nước Thục của thục Phán. “Đó là một nước đã tồn tại thật sự trong lịch sử: nước Tây Thục (tức Ai Lao)… ở phía Tây Bắc nước ta ngày nay”. “Cuối đời vua Hùng, Thục Phán đã từ đây mà xuống xâm lược nước ta. Đó là một cuộc chiến tranh dai dẳng và khốc liệt, cuối cùng nước Văn Lang bị diệt”. “Nước Tây Thục (Ai Lao) ở sát nước ta về phía tây bắc.</p>
<p>Nó nằm trên trục giao thông chủ yếu của nước ta với miền Tây Nam Di là thung lũng sông Hồng, sông Lô. Tây Thục cũng là một trạm trung gian trên con đường giao thông quốc tế thời cổ giữa Trung Quốc với các nước phía tây như Ấn Độ cổ đại”. Tác giả còn có phần chỉ cụ thể: “Đến đời Hán Minh Đế (58), Ai Lao thuộc hẳn nhà Hán. Nhà Hán lấy đất đó phân làm hai huyện Ai Lao và Bắc Nam, sau đổi thành Vĩnh Xương, nay là châu tự trị Đức Hoằng thuộc tỉnh Vân Nam (Trung Quốc) hiện nay”.</p>
<p><strong>Thuyết người Lạc Việt nói chung</strong></p>
<p>Từ chỗ chứng minh rằng Tây Âu, Tây Âu Lạc hay Âu Lạc là một nước có địa bàn chủ yếu nằm ở lưu vực sông Hồng ngày nay, trùng với bộ phận của địa bàn rộng lớn của Lạc Việt. Nó bao gồm từ lưu vực sông Hồng tới lưu vực Tây Giang ngày nay, tác giả chủ trương nước Tây Âu của người Lạc Việt,.“Trong Lạc Việt có nhiều dân tộc (theo đúng nghĩa dân tộc học ngày nay) có quan hệ lịch sử, huyết thống nào đó với nhau”.</p>
<p>Đối với thuyết Ai Lao Di, tác giả cho rằng “những thần tích ghi về việc Thục Phán cai trị ở Ai Lao là những tài liệu do người sau viết”. Về việc giao lưu giữa Giao Châu và Ích Châu thì “chỉ hạn chế đến Điền, không vượt qua khỏi Điền đến Ai Lao Di bao giờ. Ai Lao Di cũng chưa từng trở thành một nước hùng mạnh và có xu thế phát triển về phía Giao Châu bao giờ”.</p>
<p>“Văn hóa phương Bắc vào Giao Chỉ không phải qua con đường Ai Lao Di. Con đường qua Ai Lao Di là một con đường đi Thân Độc Quốc (Ấn Độ), nhưng con đường cũng chỉ đánh thông được rất muộn về sau. Thời Tần – Hán, Điền là bức thành chắn ngang đường giao lưu giữa Trung Quốc và Miến Điện, Ấn Độ ngày nay.</p>
<p>Tất cả những điều nghiên cứu trên dẫn tới việc không công nhận tên trước Âu lạc hình thành do sự sáp nhập của hai tộc Âu lạc và tộc Lạc. Mà tên nước này đã xuất hiện ngay từ trước khi thời Hùng Vương kết thúc.</p>
<p><strong>Âu Lạc đã là một nhà nước thật sự</strong></p>
<p>Thời gian nghiên cứu gần đây, vấn đề này chưa được bàn tới nhiều. Những ý kiến đã chính thức công bố nêu ra đây không phải khác nhau về điểm Âu Lạc đã là một nhà nước thật sự. Mà khác nhau ở chỗ Nhà nước Âu Lạc đã xuất hiện trên cơ sở trình độ sản xuất của thời đại đồng hay thời đại sắt.</p>
<p>Những mũi tên đồng Cầu Vực được coi là vật tiêu biểu của “văn hóa đồ đồng ở giai đoạn Âu Lạc”. Và “văn hóa vật chất của tổ tiên ta ở thời An Dương Vương vẫn chưa khác văn hóa vật chất ở thời Hùng Vương bao nhiêu, căn bản vẫn là văn hóa đồ đồng”. Đây là một trong những lập luận cho rằng nước Âu Lạc là một nhà nước của thời đại đồng.</p>
<p>Một ý kiến khác cho rằng “những di tích văn hóa vật chất thời An Dương Vương còn để lại trên khu di tích Cổ Loa đã được tìm thấy một số: như những lưỡi cày đồng ở xóm Nhồi, kho mũi tên đồng với hàng vạn chiếc mà chúng ta đều biết và có thể là lớp dưới của tầng văn hóa ở di chỉ Bãi Mèn”. Tuy rằng người viết không nói rõ, nhưng ta hiểu ý đó nói rằng thời kỳ lịch sử An Dương Vương thuộc thời đại đồng thau.</p>
<p>Di chỉ Đường Mây được phát hiện và khai quật 2 lần vào năm 1970. Nhiều cục sắt và mảnh hiện vật bằng sắt được tìm thấy, trên cơ sở đó di chỉ được tạm định thuộc sơ kỳ thời đại sắt. Đặc biệt, di chỉ Đường Mây nằm trên một doi đất cao tự nhiên ven sông Hoàng và ven bờ đầm cả và ngay dưới chân thành ngoài của thành Cổ Loa. Từ lẽ đó, người khai quật di chỉ này quả quyết rằng “nó (Đường Mây) thuộc về một thời đại trực tiếp trước thời đại của thành Cổ Loa.</p>
<p>Khi tiến hành xây thành, người ta đã đắp lũy (thành ngoài) phủ lên trên khu di chỉ này. Biến quả gò trên đó trước đây có cư dân sinh sống thành một bộ phận của thành ngoài. Vì di chỉ ấy thuộc về sơ kỳ thời đạt sắt cho nên thời hạn niên đại dưới của thành Cổ Loa không thể xưa hơn sơ kỳ thời đại sắt. Thành Cổ Loa là một công trình của thời đại sắt Việt Nam. Điều đó bác bỏ luận điểm cũ của nhiều nhà sử học và khảo cổ học nói rằng thành Cổ Loa thuộc về thời đại đồng thau phát đạt của Việt Nam”.</p>
<p>Nghiên cứu sâu hơn nữa về nước Âu Lạc, tác giả của ý kiến Cổ Loa chỉ có thể là kinh thành của một nhà nước Việt Nam thời cổ, có trước đời Hán… Nhà nước đó, theo sử cũ là Nhà nước Âu Lạc của An Dương Vương”. Từ đó tác giả còn rút ra kết luận: “Nước Âu lạc do An Dương Vương lập đã là một nhà nước thật sự”.</p>
<p>Sự phân hóa giai cấp là rõ rệt. “Tầng lớp vua chúa quý tộc ở nhà ngói sân gạch”. Xã hội này đã có trình độ phát triển kinh tế cao, có quyền lực xã hội mạnh mẽ, kỹ thuật xây dựng cao, trình độ tổ chức cao, và có mức phát triển cao, của trí tuệ và tài năng sáng tạo, có trình độ nghệ thuật quân sự rất cao.</p>
<p>Một ý kiến khác cho rằng “văn hóa Âu Lạc” tồn tại chừng 100 năm trước khi nước Âu Lạc bị tiêu diệt, nghĩa là “văn hóa Âu Lạc” có hơn nửa thế kỷ song song tồn tại với “văn hóa Văn Lang” và thuộc thời đại sắt.</p>
<p>Với nhiều giả thuyết mơ hồ đặt ra, ta chỉ có thể khẳng định Thục Phán là lãnh đạo của tộc Âu Việt. Cư trú ở thượng du hay chính xác hơn là gần tỉnh Cao Bằng &#8211; Việt Nam lúc bây giờ.</p>
<h3>Lĩnh Nam Chích Quái cho rằng đó là sự đồng hóa</h3>
<p>Truyền thuyết “Họ Hồng Bàng” trong sách Lĩnh Nam chích quái cũng phản ánh phần nào cuộc tiếp xúc và đụng độ của người Việt với người Hoa Hạ ở phương Bắc. Sách có chép” Dân phương Nam khổ vì bị người phương Bắc quấy nhiễu, không được yên sống như xưa…”. Nước Tần thành lập năm 221 TCN đã mở rộng những cuộc chiến tranh xâm lược đại quy mô ra cả hai phía bắc, nam thành lập một đế chế rộng lớn đầu tiên trong lịch sử Trung Quốc. Về phía Nam tiếp tục kế thừa và phát triển chủ trương ” bình Bách Việt” của nước Sở trước đây.</p>
<p>Tần Thủy Hoàng đã sai 50 vạn quân xâm lược đất đai của Bách Việt ở phía Nam Trường Giang. Hàng vạn quân Tần vượt biên giới tràn vào lãnh thổ phía Bắc và đông bắc nước ta lúc đó. Lúc này hai tộc người Lạc Việt và Âu Việt (Tây Âu) vốn gần gũi về dòng máu, về địa vực cư trú, về kinh tế và văn hóa lại có điều kiện liên kết chặt chẽ lại với nhau hơn trong cuộc chiến đấu chống kẻ thù chung. Theo sách Hoài Nam Tử,&nbsp;<i>“lúc đó người Việt đều vào rừng ở với cầm thú, không ai chịu để quân Tần bắt”, và “họ cùng nhau đặt người kiệt tuấn lên làm tướng để ban đêm ra đánh quân Tần”</i>&nbsp;.</p>
<p>Đó là hình thức phôi thai của lối đánh du kích và thông qua lối đánh này mà lực lượng kháng chiến của người Việt ngày càng lớn mạnh; còn quân Tần dần dần bị dồn vào thế nguy khốn và tuyệt vọng. Trên đà chiến thắng, người Việt tập hợp lực lượng tổ chức đánh lớn nhằm tiêu diệt sinh lực địch, đại phá quân Tần, giết chết chủ tướng Đồ Thư, buộc nhà Tần phải bãi binh. Đây là thắng lợi oanh liệt đầu tiên của cả dân tộc ta chống lại họa xâm lược của phong kiến phương Bắc.</p>
<p>Trong cuộc chiến đấu này, vai trò và uy tín của Thục Phán, người thủ lĩnh kiệt xuất của liên minh bộ lạc Tây Âu ngày càng được nâng cao, không chỉ ở trong bộ lạc Tây Âu mà còn có ảnh hưởng sâu rộng trong bộ lạc Lạc Việt. Sau khi cuộc kháng chiến kết thúc thắng lợi, trong điều kiện cộng đồng cư dân Lạc Việt – Tây Âu đã hình thành và uy tín ngày càng cao của Thục Phán.</p>
<p>Thục Phán đã thay thế Hùng Vương, tự xưng là An Dương Vương, lập ra nước Âu Lạc. Sách&nbsp;<i>Việt sử lược</i>&nbsp;chép rằng&nbsp;<i>“Hùng Vương bị con vua Thục là Phán đánh đuổi mà lên thay”</i>&nbsp;. Còn một số thần tích và truyền thuyết dân gian lại cho rằng sau nhiều cuộc xung đột, cuối cùng Hùng Vương theo lời khuyên của con rể là Thánh Tản Viên đã nhường ngôi cho Thục Phán.</p>
<h3>Xây thành Cổ Loa</h3>
<p>Sau chiến thắng trước quân Tần, An Dương Vương quyết định giao cho tướng Cao Lỗ xây thành Cổ Loa nhằm củng cố thêm khả năng phòng thủ quân sự. Tục truyền rằng thành xây nhiều lần nhưng đều đổ. Sau có thần Kim Quy hiện lên, bò quanh bò lại nhiều vòng dưới chân thành. Thục An Dương Vương bèn cho xây theo dấu chân Rùa vàng. Từ đó, thành xây không đổ nữa. An Dương Vương cũng phát triển thuỷ binh và cho chế tạo nhiều vũ khí lợi hại, tạo lợi thế quân sự vững chắc cho Cổ Loa.</p>
<p>Di tích của thành Cổ Loa vẫn còn lưu lại cho đến nay, cách trung tâm Hà Nội khoảng 20km về phía đông bắc. Đền thờ An Dương Vương nằm ở trung tâm di tích này. Các nghiên cứu khảo cổ học tại đây vẫn tiếp tục làm sáng tỏ các thời kỳ lịch sử mà thành đã trải qua.</p>
<h3>Mắc mưu và sự sụp đổ của nhà nước Âu Lạc</h3>
<p>Triệu Đà buộc phải dùng kế nội gián bằng cuộc kết hôn giữa con trai mình là Trọng Thủy và con gái An Dương Vương là Mỵ Châu. Sau khi nắm được bí mật quân sự của An Dương Vương thông qua con trai, Triệu Đà đã thành công trong việc chinh phục Âu Lạc, buộc An Dương Vương bỏ chạy và tự tử, kết thúc thời kỳ An Dương Vương.</p>
<p>Về năm mất của triều đại An Dương Vương, các tài liệu ghi chép khác nhau. Đa phần sách sử Việt Nam&nbsp; đều chép là An Dương Vương mất nước năm 208 TCN. Sách giáo khoa của Việt Nam căn cứ vào Sử ký của Tư Mã Thiên ghi nước Âu Lạc mất năm 179 TCN. Sở dĩ như vậy vì Sử Ký chép là Triệu Đà diệt nước Âu Lạc “Sau khi Lã Hậu chết”, mà Lã Hậu chết năm 180 TCN, do đó nước Âu Lạc mất khoảng năm 179TCN.</p>
<h3>Giá trị lịch sử to lớn</h3>
<p>Nước Âu Lạc của An Dương Vương chỉ tồn tại trong khoảng thời gian ngắn (khoảng gần 30 năm), nhưng nó cũng đã có những đóng góp to lớn vào trong tiến trình phát triển của lịch sử đất nước. Thời kỳ Âu Lạc được đưa vào thời kỳ lập nước của sử Việt.</p>
', 'An Dương Vương tên thật là Thục Phán. Ông là vị vua duy nhất của triều đại Âu Lạc. Niên đại trị vì của An Dương Vương theo nhiều sử sách ghi lại là khác nhau. Trong Đại Việt Sử Kỳ Toàn Thư cho rằng thời gian ông làm vua kéo dài trong 50 năm [&hellip;]', 1045, 'post', '2018-06-22 08:54:15', '2023-04-23 12:33:57');
