INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (995, 'Bàn về 18 đời vua Hùng &#8211; Truyền thuyết và những phân tích của sử gia', '18-doi-vua-hung', '<p>18 đời vua Hùng kéo dài trong 2622 năm (Từ 2879 TCN đến 258 TCN). Không thể phủ nhận các đời vua Hùng là thủy tổ của người Việt. Nhưng bên trong đó còn rất nhiều giả thuyết và những nghi ngờ về sự chính xác trong đó. Nếu chia 2622 năm kéo dời của 18 đời vua Hùng. Thì mỗi đời có trung bình 145,666 năm. Nó lớn hơn hẳn tuổi thọ trung bình của người Việt thời bấy giờ. Và còn nhiều câu hỏi được đặt ra hơn nữa. Hãy cũng Huynh Hieu Travel tìm hiểu hết những câu chuyện, phân tích và giải đáp những thắc mắc về vua Hùng.</p>
<h2>18 Đời Vua Hùng &#8211; Những Bí Ẩn Cần Được Giải Đáp</h2>
<h3>Nguồn gốc vua Hùng &#8211; truyền thuyết 100 bọc trứng</h3>
<p>Nhắc đến nguồn gốc của vua Hùng phải kể đến thời Lộc Tục. Lộc Tục còn có hiệu là Kinh Dương Vương. Kinh Dương Vương là người cai quản những bộ lạc ở phương Nam. Sau đó ông lấy Thần Long, rồi sinh ra Lạc Long Vương.</p>
<p><em>Tìm hiểu về Kinh Dương Vương:&nbsp;<a href="http://bit.ly/2tqyAbi">http://bit.ly/2tqyAbi</a></em></p>
<p>Sau đó Lạc Long Quân thay cha cai quản miền đất phía Nam. Nhìn thấy Âu Cơ xinh đẹp, Lạc Long Quân biến thành chàng trai dũng mạnh, rước nàng về làm vợ. Hai người ở với nhau một năm, Âu Cơ sinh ra 100 bọc trứng. 100 bọc trứng nở ra 100 người con trai anh dũng.</p>
<p><em>Tìm hiểu về Lạc Long Quân:&nbsp;<a href="https://huynhhieutravel.com/lac-long-quan/">https://huynhhieutravel.com/lac-long-quan/</a></em></p>
<p>Lạc Long Quân nói:&#8221;Ta là loài rồng, sinh trưởng ở thủy tộc; nàng là giống tiên, người trên đất, vốn chẳng như nhau, tuy rằng khí âm dương hợp mà lại có con nhưng phương viên bất đồng, thủy hỏa tương khắc, khó mà ở cùng nhau trường cửu. Bây giờ phải ly biệt, ta đem năm mươi con trai về Thủy phủ, phân trị các xứ, năm mươi con trai theo nàng ở trên đất, chia nước mà cai trị, dù lên núi xuống nước nhưng có việc thì cùng nghe không được bỏ nhau&#8221;.</p>
<p><figure id="attachment_993" aria-describedby="caption-attachment-993" style="width: 1000px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-993" src="https://media.huynhhieutravel.com/lac-long-quan-va-au-co.jpg" alt="Lạc Long Quân và Âu Cơ" width="1000" height="744" srcset="https://media.huynhhieutravel.com/lac-long-quan-va-au-co.jpg 1000w, https://media.huynhhieutravel.com/lac-long-quan-va-au-co-768x571.jpg 768w" sizes="(max-width: 1000px) 100vw, 1000px" /><figcaption id="caption-attachment-993" class="wp-caption-text">Minh họa Lạc Long Quân và Âu Cơ</figcaption></figure></p>
<p>Từ đó, Lạc Long Quân đem 50 người con ra biển. Âu Cơ mang 50 người con lên núi ở tại Phong Châu. Đưa người con trưởng lên làm vua, tự là Hùng Vương.</p>
<h3>Phân chia nhà nước thời vua Hùng</h3>
<p>Quốc hiệu khi vua Hùng lên ngôi đặt là Văn Lang. Vua Hùng chia Văn Lang thành 15 bộ: Giao Chỉ, Chu Diên, Vũ Ninh, Phúc Lộc, Việt Thường, Ninh Hải, Dương Tuyền, Lục Hải, Vũ Định, Hoài Hoan, Cửu Chân, Bình Văn, Tân Hưng, Cửu Đức; đóng đô ở bộ Văn Lang, Phong Châu.</p>
<p>Vua Hùng đặt em thứ làm Tướng võ, Tướng văn. Tướng văn gọi là Lạc Hầu, Tướng võ là Lạc Tướng, con trai vua gọi là Quan Lang, con gái vua gọi là Mị Nương, quan Hữu ty gọi là Bố chính, thần bộc nô lệ gọi là nô tỳ, xưng thần là khôi, đời đời cha truyền con nối gọi là phụ đạo, thay đời truyền nhau cho đến hiệu là Hùng Vương không đổi.</p>
<p>Về ngoại giao vua Hùng có chính sách hòa hữu với Trung Quốc. Ông từng đem nhiều lễ vật sang tặng một số đời vua Trung Quốc.</p>
<h3>Sự thật về 18 đời vua Hùng &#8211; Chi tiết và nhận định</h3>
<p>18 đời vua Hùng trị vì hơn 2622 năm. Xét về mặt thời gian là khó khả thi. Mỗi đời vua sẽ kéo dài trung bình đến gần 150 năm. Điều vô lý này đã gây ra nhiều tranh cãi trên các diễn đàn lịch sử khác nhau. Nhưng nếu nhìn nhận theo một góc độ khác thì nó lại trở nên có lý.</p>
<p>Theo nhận định trong “Hùng Vương sự tích ngọc phả cổ truyện” do Nguyễn Như Đỗ thời nhà Hậu Lê.&nbsp; Thì chữ “đời” vua thường hay dùng phải hiểu là chữ “thế” trong Hán tự, nghĩa là không phải là một đời người mà là “một dòng gồm nhiều đời” hay “chi”. “Hùng Vương sự tích ngọc phả cổ truyện” chép rằng thời đại Hùng Vương kéo dài 2.622 qua 47 đời vua trị vì với 18 chi, mỗi một chi qua mấy đời vua. Mà “chi” đầu tiên lại được chép là Kinh Dương Vương.</p>
<p>18 chi được sắp theo bát quái (8 quái): 1 Càn (trời) (☰), 2 Đoài (đầm) (☱), 3 Ly (hỏa) (☲), 4 Chấn (sấm) (☳), 5 Tốn (gió) (☴), 6 Khảm (nước) (☵), 7 Cấn (núi) (☶), 8 Khôn (đất) (☷) và 10 thiên can Giáp, Ất, Bính, Đinh, Mậu, Kỷ, Canh, Tân, Nhâm, Quý.</p>
<p>18 chi thời Vua Hùng theo “Hùng Vương sự tích ngọc phả cổ truyện” lần lượt là:</p>
<ul>
<li>Chi Càn: Kinh Dương Vương, sinh năm nhâm ngọ 2919 TCN. Trị vì 86 năm từ Nhâm Tuất 2879 TCN đến Đinh Hợi 2794 TCN.</li>
<li>Chi Khảm: Lạc Long Quân tên húy là Sùng Lãm tức Hùng Hiền Vương. Chi này kéo dài 269 năm từ Mậu Tý 2793 đến Bính Thìn 2525 TCN. Thời kỳ này được truyện cổ tích họ “Hồng Bàng truyền kỳ” gọi là huyền sử Rồng Tiên.</li>
<li>Chi Cấn: Hùng Quốc Vương tên húy là Hùng Lân kéo dài 271 năm, từ 2524 đến 2253 TCN. Thời kỳ này theo truyền thuyết thì mẹ Âu dẫn 50 con (Tức 50 tộc người Bách Việt) ở lại vùng cao rồi cùng nhau suy cử người con trưởng lên làm vua, lấy hiệu là Hùng vương đóng đô ở Châu Phong. Cũng từ năm 2524 tên nước được đổi thành Văn Lang.</li>
<li>Chi Chấn: Hùng Hoa Vương tên húy là Hùng Bửu Lang, chi này kéo dài 342 năm.</li>
<li>Chi Tốn: Hùng Hi Vương tên húy là Bảo Long, chi này kéo dài 200 năm.</li>
<li>Chi Ly: Hùng Hồn Vương, tên húy là Long Tiên Lang, chi này gồm 2 đời vua, kéo dài 81 năm.</li>
<li>Chi Khôn: Hùng Chiêu Vương, tên húy là Quốc Lang, sinh năm 1659 TCN, lên ngôi năm 12 tuổi, gồm 5 đời vua, dài 200 năm.</li>
<li>Chi Đoài: Hùng Vĩ Vương, tên húy là Văn Lang, chi này gồm 5 đời vua kéo dài 100 năm. Thời kỳ này, truyền kỳ lịch sử kể rằng giặc Ân sang đánh nước ta bị Phù Đổng Thiên Vương đánh cho tan tác. Sử Trung Quốc ghi là đời Cao Tông triều Ân đánh nước Quỷ Phương 3 năm đóng quân ở đất Kinh.</li>
<li>Chi Giáp: Hùng Định Vương, tên húy là Chân Nhân Lang, Chi này gồm 3 đời vua, kéo dài 80 năm.</li>
<li>Chi Ất: Hùng Uy Vương tên húy là Hoàng Long Lang, gồm 3 đời vua dài 90 năm.</li>
<li>Chi Bính: Hùng Trinh Vương húy Hưng Đức Lang, chi này gồm 4 đời vua kéo dài 107 năm.</li>
<li>Chi Đinh: Hùng Vũ Vương tên húy Đức Hiền Lang, gồm 3 đời vua, kéo dài 96 năm.</li>
<li>Chi Mậu: Hùng Việt Vương, tên húy là Tuấn Lang, chi này gồm 5 đời vua, kéo dài 105 năm.</li>
<li>Chi Kỷ: Hùng Anh Vương, tên húy là Viên Lang, gồm 4 đời vua, dài 89 năm.</li>
<li>Chi Canh: Hùng Triệu Vương, tên húy là Chiêu Lang, chi này gồm 3 đời vua, kéo dài 94 năm.</li>
<li>Chi Tân: Hùng Tạo Vương, tên húy là Đức Quân Lang, chi này gồm 3 đời vua, kéo dài 92 năm. Trong “Hùng Triều Ngọc Phả”, Thần Phả xã Tiên Lát, huyện Việt Yên, tỉnh Hà Bắc có ghi rõ là đến đời Hùng Vương thứ 16 dời đô xuống Phong Châu Thượng.</li>
<li>Chi Nhâm: Hùng Nghi Vương, tên húy Bảo Quang, lên ngôi năm 9 tuổi, gồm 4 đời vua, dài 160 năm.</li>
<li>Chi Quý: Hùng Duệ Vương, tên húy là Huệ Vương Lang, lên ngôi năm 14 tuổi, chi này gồm 3 đời vua, từ năm 337 TCN đến năm 258 TCN, tức là được 79 năm.</li>
</ul>
<h3>Tại sao mùng 10 tháng 3 là ngày giỗ vua Hùng?</h3>
<p>Phải chăng vua Hùng đầu tiên mất vào ngày mùng 10 tháng 3? Hay triều đại kết thúc vào mùng 10 tháng 3? Những ghi chép lịch sử ghi nhận lại thì những giả thuyết đó đều không thuyết phục.</p>
<ul>
<li>Giả thuyết thứ 1: Trong văn hóa người Việt thì chúng ta được xem là con rồng cháu tiên. Rồng là thìn, mà tháng 3 là tháng của rồng &#8211; tháng Thìn. 10 thiên can được đặt tên cho 10 đời vua Hùng vì thế lấy ngày 10 là ngày giỗ.</li>
<li>Giả thuyết thứ 2: Trước đây ngày giỗ vua Hùng không được xác định rõ ràng. Nhiều nơi làm lễ giỗ nhiều ngày khác nhau theo bản mệnh tốt từng vùng. Thường là vào những ngày xuân thu. Lễ cúng Tổ ở địa phương thì lại được cử hành vào ngày 12.3 âm lịch kết hợp với thờ Thổ kỳ. Thường khi con cháu ở xa về sẽ làm giỗ trước một ngày chứ không mở hội lớn với quy mô toàn quốc. Nhận thấy điều này, Tuần phủ Phú Thọ ông Lê Trung Ngọc vào năm 1917 (niên hiệu Khải Định năm thứ nhất) đã làm bản tấu trình lên Bộ Lễ, xin định lệ lấy ngày 10.3 âm lịch hàng năm làm ngày Quốc tế.&nbsp;Từ đó về sau, cứ vào ngày 10.3 nhân dân cả nước lại hướng về vùng đất Cội nguồn &#8211; xã Hy Cương, Lâm Thao, Phú Thọ để tôn vinh công lao của các vị vua Hùng.</li>
</ul>
<h3>Kinh Tế Thời Hùng Vương</h3>
<p>Vào thời kỳ này săn bắt hái lượm vẫn giữ vai trò quan trọng trong đời sống kinh tế của người dân Lạc Việt. Nhưng nghề nông và đánh bắt đã bắt đầu có bước phát triển vượt bật. Kể cả câu chuyện truyền thuyết 100 bọc trứng vẫn có nói 50 người con xuống biển.</p>
<p>Thuở bấy giờ, người dân khi đi đánh bắt thường bị nhiều loài cá dữ sát hại. Vua Hùng dạy dân cách xăm mình những con cá dữ như cá sấu để chúng tưởng là đồng loại mà không sát hại. Từ đó tộc Việt bắt đầu có tục xăm mình. Tục này kéo dài đến vua Trần Anh Tông (năm 1293 &#8211; năm 1314) mới bắt đầu thoái trào.</p>
<p>Nghề rèn cũng bắt đầu phát triển mạnh mẽ hơn nhờ sự phát triển của ngư nghiệp. Những lưỡi câu bằng đồng, mũi lao có ngạnh bằng xương được sản xuất để người dân chống chọi với lũ cá dữ.</p>
<p>Người dân bắt đầu trồng lúa và vua Hùng cũng hay thường lên núi hàng năm để cầu vụ mùa bội thu.&nbsp;Chỗ núi vua lên khấn vái lúa về sau được gọi là núi Hùng (thuộc xã Hy Cương, huyện Phong Châu, Vĩnh Phú). Lúc bấy giờ những ruộng lúa thời vua Hùng gọi là ruộng Lạc (Chỉ những chỗ đồng bằng trũng nằm ven sông Hồng, sông Mã). Dân theo thủy triều lên xuống mà làm ruộng theo vụ, gọi là Lạc dân.</p>
<p>Lạc dân dùng phương pháp thủy nậu để cấy lúa bằng cách lấy chân đạp cho cỏ sụt bùn rồi mới lấy cấy lúa lên. Ban đầu là những giống lúa hoang. Dần về sau được lai tạo và chọn lọc thành những hạt gạo nếp dẻo thơm ngon hơn. Và sau này người dân còn mở rộng trồng các loại rau và nông sản khác.</p>
<p>Kỹ thuật luyện kim phát triển mạnh, cư dân Lạc Việt đã biết làm ra những công cụ sản xuất bằng kim loại như rìu đồng. Và quan trọng nhất là cày đồng và lưỡi hái bằng đồng ảnh hưởng mạnh đến sinh hoạt nông nghiệp. Lưỡi cày thời ấy có hình cánh bướm hoặc hình tam giác.</p>
<p>Những dụng cụ sinh hoạt như mâm đồng, đục, kim dao, lưỡi câu, chuông và đồ trang sức cũng được sản xuất với số lượng đáng kể. Ngoài ra, thời Lạc Việt đã có nghề luyện sắt (di tích Gò Chiền Vậy) và nghề gốm.</p>
<h3>Cư Trú</h3>
<p>Nhà được dựng theo kiểu nhà sàn. Nguyên liệu là gỗ, tre, nứa, lá. Nhà có mái cong hình thuyền hoặc mái tròn và sàn thấp. Nhà chưa có vách, đuôi mái gối sát sàn nhà. Cầu thang lên đặt trước nhà. Các ngôi nhà được bố trí quây tụ ở ven đồi, đỉnh gò, chân núi, nếu gần sông suối thì nằm trên các giải đất cao để tránh lụt lội.</p>
<h3>Trang phục</h3>
<p><strong>Đầu tóc</strong> để 3 kiểu chính: Cắt ngang vai cho cả nam và nữ, búi tóc lên đầu cho cả nam và nữ, riêng kiểu tóc kết đuôi sam và có vành khăn nằm ngang trán thì chỉ dùng cho phụ nữ.</p>
<p>Về <strong>mặc</strong> thì nam nữ đã có trang phục riêng:&nbsp;Nữ mặc váy, thân để trần, đi chân đất. Váy có hai kiểu là kín và mở, ngắn đến đầu gối, có khi có đệm váy. Phụ nữ giàu có ăn mặc có phần chải chuốt hơn, khăn chóp nhọn trùm lên búi tóc, đủ cả váy, áo và yếm, áo cánh xẻ ngực, thắt lưng có trang trí. Váy kín có trang trí, buông chùng đến gót chân, đệm váy có hình chữ nhật cũng có trang trí, thả trước bụng hay sau mông.</p>
<p>Nam đi chân không, ở trần, mặc khố. Khố có hai kiểu, kiểu quấn một vòng và kiểu quấn hai vòng. Có đuôi thả đàng sau.</p>
<p>Trang phục lễ hội không phân biệt nam nữ. Thường là váy kết bằng lá hay bằng lông vũ. Mũ kết bằng lông chim có cắm thêm bông lau ở phía trên hoặc phía trước.</p>
<p><strong>Đồ trang sức</strong>: người thời Hùng Vương cả nam lẫn nữ đều rất ưa thích dùng đồ trang sức. Nam cũng như nữ đều đeo vòng tai. Ngoài ra, các trang sức hạt chuỗi, nhẫn và vòng tay rất phổ biến. Hình dáng của vòng tay rất đa dạng: hình vành khăn, hình tròn, hình tròn có mấu. Hạt chuỗi có hình trụ, hình trái xoan, hình tròn. Vòng nhẫn hình tròn hoặc hình bện thừng. Vòng tay có tiết diện chữ nhật, hình ống, hoặc có cánh.</p>
<p>Chất liệu của các đồ trang sức là những kim loại cao cấp như vàng bạc. Thường là bằng đá, đồng thau, rất ít khi bằng ngọc nhưng được tạo thành với khiếu thẩm mỹ cao.</p>
<h3>Ăn uống</h3>
<p>Thức ăn chính là gạo nếp tẻ, đã có dụng cụ bếp núc như nồi, chõ. Sách Lĩnh Nam Chích Quái ghi lại là dân Lạc đã biết làm mắm: &#8220;Lấy cầm thú, cá, ba ba làm mắm&#8221;. Họ cũng biết làm rượu, làm bánh. Thức ăn thường là cá, gà, vịt, chim, heo, chó, trâu, hươu, nai, cáo, khỉ, ba ba, rùa, cua ốc&#8230; với các hương liệu: gừng muối, trầu cau, đất hun.</p>
<h3>Văn Hóa</h3>
<p><strong>Hôn nhân:&nbsp;</strong>Có một số tục lệ như lấy gói đất, gói muối tượng trưng cho tình nghĩa vợ chồng. Vì thế có câu: &#8220;Tục hôn nhân lấy gói đất (hoặc lấy gói muối) làm đầu&#8221;. Một số nghi thức khác trong hội lễ ghi nhận được là ném bùn, ném đất và hoa quả vào người chàng rể. Nghi thức chủ yếu nhất là hai vợ chồng mới ăn chung bát cơm nếp. Sau khi ăn bát cơm nếp, họ được cộng đồng công nhận là vợ chồng.</p>
<p><strong>Tang ma:&nbsp;</strong>Khi trong nhà có người chết, người ta giã vào cối, đó là tín hiệu thông tin cho hàng xóm, láng giềng biết để đến giúp đỡ. Người chết có quyền đem theo một số tài sản để sử dụng trong cuộc sống khác. Các đồ tùy táng là những đồ dùng hàng ngày và đồ trang sức.Thời ấy người chết được hỏa táng hay được chôn cất. Các nhà khảo cổ học đã đào được các quan tài độc mộc. Đó là một thân cây khoét rỗng có hình dáng giống như chiếc thuyền độc mộc.</p>
<p><strong>Một số phong tục khác</strong> như:&nbsp;Khi trẻ sơ sinh ra đời, dân Lạc có tục lệ lót ổ cho trẻ bằng lá chuối tươi. Khi trẻ lớn lên được làm lễ thành đinh, Lễ thành đinh mang tính thử thách năng lực của các thanh niên, thường được tổ chức những buổi thi tài trong các ngày hội. Sau lễ thành đinh, thanh niên trở thành thành viên lao động mới của xã hội.</p>
<p><strong>Vẽ</strong>: Nghệ thuật vẽ đã rất phổ biến với các hoa văn đa dạng trên các đồ gốm, trên các trống đồng. Không những thế cư dân Văn Lang đã biết dùng màu để vẽ. Tục xăm mình là một minh chứng về nghệ thuật vẽ màu của người Văn Lang.</p>
<p>Đề tài chính của nghệ thuật này là con người đang hoạt động, đang sống hồn nhiên. Đó là quang cảnh nhảy múa, thổi khèn, giã cối&#8230; hoặc là quan hệ giữa con người và thiên nhiên. Mặt trống đồng như một vũ trụ mà trung tâm là mặt trời. Hoạt động của con người quây tròn chung quanh mặt trời đang tỏa sáng.</p>
<p><strong>Tạc tượng</strong>: Chất liệu là đất nung, đồng thau, đá&#8230; những bức tượng mang dáng vẻ rất hồn nhiên, sinh động, ví dụ như bức tượng người ngồi thổi khèn, tượng người cõng nhau nhảy múa thổi khèn cho thấy sự thoải mái, thanh nhàn trong cuộc sống đơn giản. Bên cạnh đề tài là con người còn có các động vật gần trong sinh hoạt của con người: gà, chó, chim&#8230;</p>
<p><strong>Âm nhạc</strong>: Qua các hiện vật khảo cổ tìm được qua hình ảnh trên các trống đồng, ta thấy cư dân Văn Lang rất ưa ca hát, nhảy múa. Họ hát đối đáp, đánh trống, đánh cồng hoặc hòa tấu cùng nhau với đủ các dụng cụ âm nhạc mà họ đã sáng tạo được như sau: Trống đồng có âm thanh dũng mãnh: trống da, cồng chiêng (mỗi giàn chiêng có từ 6 đến 8 chiếc), chuông nhạc, phách, khèn&#8230;</p>
<p><strong>Hội lễ:&nbsp;</strong>Hội lễ là một phần trong cuộc sống của dân Lạc. Trong các buổi lễ hội có những sinh hoạt như sau:</p>
<ul>
<li>Tục lệ đánh trống đồng: hoặc do một người đánh hoặc hòa tấu từng cặp trống đực cái, người đánh trống bận lễ phục hình chim ở tư thế ngồi hay đứng.</li>
<li>Múa nhảy ca hát: Người trình diễn cũng bận lễ phục hình chim, có múa hóa trang, múa vũ trang, múa hát giao duyên nam nữ. Múa hóa trang thường đội mũ có gắn lông chim, có từ ba đến bảy người, có người cầm vũ khí, cầm khèn.</li>
<li>Hội giã cối: từng đôi nam nữ cầm chày dài giã cối tròn tạo nên hình ảnh tượng trưng cho sự sinh phồn.</li>
<li>Các cuộc đua thuyền hào hứng với những chiếc thuyền độc mộc mình thon, mũi cong, đuôi én.</li>
</ul>
<p>Mọi sinh hoạt trên đều gắn với điều cầu mong thiết thực của cuộc sống như mong mưa thuận, gió hòa, mong được mùa, mong sinh sản được nhiều.</p>
<h3>Tín ngưỡng</h3>
<p>Dân Lạc thờ các lực lượng thiên nhiên (thần núi, thần sông, thần đất); thờ các vật thiêng (thần rồng, chim, hổ); thờ anh hùng (Phù Đổng)</p>
<p><em>Thông tin được tổng hợp lại từ các nguồn Wiki, sách Lĩnh Nam Chích Quái, Đại Việt Sử Ký Toàn Thư và một số diễn đàn lịch sử.</em></p>
', '18 đời vua Hùng kéo dài trong 2622 năm (Từ 2879 TCN đến 258 TCN). Không thể phủ nhận các đời vua Hùng là thủy tổ của người Việt. Nhưng bên trong đó còn rất nhiều giả thuyết và những nghi ngờ về sự chính xác trong đó. Nếu chia 2622 năm kéo dời của [&hellip;]', 979, 'post', '2018-06-22 06:47:57', '2023-04-23 12:33:59');
