INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (990, 'Lạc Long Quân', 'lac-long-quan', '<p>Lạc Long Quân tên húy là Sùng Lãm (Thế kỷ thứ 8 TCN &#8211; 7 TCN). Ông là con của Kinh Dương Vương và Thần Long. Ông được xem là thủy tổ của dân tộc Việt Nam. Truyền thuyết bọc trăm trứng nở trăm người con của Lạc Long Quân và Âu Cơ. 50 người con lên rừng và 50 người con xuống biển. Con trai ông là tù trưởng bộ lạc Văn Lang (vua Hùng). Người có công thống nhất tất cả bộ lạc và lập nên nhà nước Văn Lang. Xưng hiệu là vua Hùng.</p>
<h2>Lạc Long Quân</h2>
<p><figure id="attachment_991" aria-describedby="caption-attachment-991" style="width: 560px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="wp-image-991 size-full" src="https://media.huynhhieutravel.com/lac-long-quan.jpg" alt="Lạc Long Quân" width="560" height="640"><figcaption id="caption-attachment-991" class="wp-caption-text">Ảnh minh họa Lạc Long Quân</figcaption></figure></p>
<p>Theo truyền thuyết Lạc Long Quân là con của <a href="http://bit.ly/2tqyAbi">Kinh Dương Vương</a>. Bạn có thể tìm hiểu Kinh Dương Vương qua link:&nbsp;<a href="http://bit.ly/2tqyAbi">http://bit.ly/2tqyAbi</a>.</p>
<h3>Truyền Thuyết Trong Lĩnh Nam Chích Quái</h3>
<p style="font-weight: 400;">Lạc Long Quân dạy dân việc cày cấy nông tang, đặt ra các đẳng quân, thần, tôn, ti, các đạo cha con, vợ chồng, đôi khi trở về Thủy Phủ mà trăm họ vẫn yên vui vô sự, không biết do đâu được thế. Hễ dân có việc lại lớn tiếng gọi Long Quân rằng: &#8220;Bố ơi! sao không lại cứu chúng tôi&#8221;. Long Quân tới ngay, sự linh hiển của Long Quân, người đời không ai lường nổi.</p>
<p style="font-weight: 400;">Đế Nghi truyền ngôi cho con là Đế Lai, cai trị Bắc phương. Nhân khi thiên hạ vô sự bèn sai quần thần là bọn Xuy Vưu thay mình trông coi quốc sự rồi đi tuần xuống nước Xích Quỷ ở phía Nam. Khi đó, Long Quân đã về Thủy Phủ, trong nước không có chúa.</p>
<p style="font-weight: 400;">Đế Lai bèn để ái nữ là Âu Cơ và các thị tỳ ở lại nơi hành tại rồi đi chu du thiên hạ, ngắm các nơi danh lam thắng cảnh. Thấy hoa kỳ cỏ lạ, trân cầm dị thú, ngọc ngà vàng bạc&#8230; các thứ đá quý, các cây trầm, đàn cùng các sơn hào hải vật không thiếu thứ gì, khí hậu bốn mùa không lạnh không nóng, Đế Lai rất ái mộ, vui quên trở về.</p>
<p style="font-weight: 400;">Dân phương Nam khổ vì bị người Bắc phương quấy nhiễu, không được yên sống như xưa mới cùng gọi Long Quân rằng: &#8220;Bố ơi ở đâu mà để cho dân Bắc xâm nhiễu&nbsp;chúng&nbsp;dân&#8221;.Long Quân đột nhiên trở về, thấy Âu Cơ có dung mạo đẹp đẽ kỳ lạ, trong lòng vui mừng, bèn hóa thành một trang thiếu niên phong tư tú lệ, tả hữu kẻ hầu người hạ đông đúc, vừa đi vừa ca hát đánh trống. Cung điện tự nhiên dựng lên.&nbsp;Âu Cơ vui lòng theo Long Quân. Long Quân giấu Âu Cơ ở Long Đài.</p>
<p style="font-weight: 400;">Đế Lai trở về, không thấy Âu Cơ, sai quần thần đi tìm khắp thiên hạ. Long Quân có phép thần thông biến hóa thành trăm hình vạn trạng yêu tinh, quỷ sứ, rồng, rắn, hổ, voi&#8230; làm cho bọn đi tìm đều sợ hãi không dám sục sạo, Đế Lai bèn phải trở về.</p>
<h3>Truyền Thuyết Lạc Long Quân Diệt Ngư Tinh</h3>
<p>Ở biển Đông có con tinh ngư xà (còn gọi là Ngư Tinh) dài hơn năm mươi trượng, chân nhiều như chân rết, biến hóa vạn trạng, linh dị khôn lường, khi đi thì ầm ầm như mưa, lại ăn được thịt người nên ai cũng sợ.</p>
<p>Thuở ấy có hòn đá Ngư Tinh, răng đá lởm chởm cắt ngang bờ bể, ở dưới đá có hang, Ngư Tinh sống ở trong đó. Vì sóng gió hiểm trở, không có lối thông, dân muốn mở một đường đi khác nhưng đá rắn khó đẽo. Thuyền của nhân dân đi qua chỗ này thường hay bị Ngư Tinh làm hại. Đêm kia có bọn người tiên đục đá làm đường đi để cho hành nhân có chỗ qua lại. Ngư Tinh bèn hóa làm con gà trắng gáy ở trên núi. Quần tiên nghe tiếng ngỡ rằng đã rạng đông bèn cùng bay lên trời.</p>
<p>Lạc Long Quân thương dân bị hại bèn hóa phép thành một chiếc thuyền của thường dân, hạ lệnh cho quỷ Dạ Thoa ở Thủy Phủ cấm hải thần nổi sóng, rồi chèo thuyền đến bờ hang đá Ngư Tinh, giả cách cầm một người sắp ném vào cho nó ăn. Ngư Tinh há miệng định nuốt. Long Quân cầm một khối sắt nung đỏ ném vào miệng cá. Ngư Tinh chồm lên quẫy mình quật vào thuyền. Long Quân cắt đứt đuôi cá, lột da phủ lên trên núi nay chỗ đó gọi là Bạch Long Vĩ, còn cái đầu trôi ra ngoài bể biến thành con chó. Long Quân bèn lấy đá ngăn bể rồi chém nó. Nó biến thành cái đầu chó, nay gọi là Cẩu Đầu Sơn. Thân trôi ra ngoài Mạn Cầu, chỗ đó nay gọi là Mạn Cầu Thủy (còn gọi là Cẩu Đầu Thủy).</p>
<h3>Tại Sao Vua Hùng Chứ Không Phải Lạc Long Quân Là Thủy Tổ?</h3>
<p>Nhiều luận cứ của những nhà sử học cho rằng Lạc Long Quân thật chất chỉ là trong truyền thuyết. Chúng ta thiếu nhiều căn cứ để xác định rằng Lạc Long Quân thật sự có tồn tại trong lịch sử. Riêng vua Hùng, ông là người thật sự có và đã thống nhất các bộ tộc Lạc Việt. Ông cũng là người lập nên một nhà nước có chính quyền đầu tiên mang tên Văn Lang của dân tộc Việt Nam.</p>
<p>Vua Tự Đức đã nhận định đây là những &#8220;câu truyện đề cập đến ma trâu, thần rắn, hoang đường không có chuẩn tắc&#8221; và kiên quyết loại Kinh Dương và Lạc Long ra khỏi chính sử bằng cách đưa xuống phụ chú dưới niên kỷ Hùng vương, để &#8220;cho hợp với cái nghĩa lấy nghi truyền nghi&#8221;.</p>
<h3>Nhiều Nơi Vẫn Lập Đền Thờ Phụng Lạc Long Quân</h3>
<p>Tuy rằng việc xác định thủy tổ còn chưa rõ ràng. Nhưng chúng ta cũng không bỏ quên công lao của vị cha vua Hùng này. Nhiều đình thờ được lập ra thờ phụng vị Tổ của đất nước này. Đặc biệt là ở dân làng Bình Đà.</p>
<p>Suốt sáu thế kỉ, đích thân 16 vị vua của các triều đại đều đích thân về Bình Đà dâng lễ Quốc tổ. Đã có 16 hiến sắc suy tôn Lạc Long Quân là &#8220;Khai Quốc Thần&#8221; (các hiến sắc này đều được lưu giữ tại Đền Nội Bình Đà và bảo tàng Lịch sử quốc gia)</p>
<p>Ngoài ra, Lăng và đền thờ của Kinh Dương Vương ở Bắc Ninh được nhiều đời triều đại vua phong kiến Việt Nam thờ phụng. Đến bây giờ ở Bắc Ninh vẫn tổ chức lễ hội thờ cúng Kinh Dương Vương hàng năm. Tên ông lấy làm tên đường nhiều tỉnh thành ở nước ta, đặc biệt thành phố Hồ Chí Minh cũng có tên đường của ông.</p>
<p>Bạn có thể tìm hiểu thêm về cha của Lạc Long Quân là Kinh Dương Vương:&nbsp;<a href="https://huynhhieutravel.com/kinh-duong-vuong/">https://huynhhieutravel.com/kinh-duong-vuong/</a></p>
', 'Lạc Long Quân tên húy là Sùng Lãm (Thế kỷ thứ 8 TCN &#8211; 7 TCN). Ông là con của Kinh Dương Vương và Thần Long. Ông được xem là thủy tổ của dân tộc Việt Nam. Truyền thuyết bọc trăm trứng nở trăm người con của Lạc Long Quân và Âu Cơ. 50 người [&hellip;]', 993, 'post', '2018-06-21 15:21:03', '2023-04-23 12:34:00');
