INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (4707, 'Home', 'home', '		<div data-elementor-type="wp-page" data-elementor-id="4707" class="elementor elementor-4707" data-elementor-post-type="page">
				<div class="elementor-element elementor-element-10966df e-flex e-con-boxed e-con e-parent" data-id="10966df" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
		<div class="elementor-element elementor-element-6364387 e-con-full e-flex e-con e-child" data-id="6364387" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
				<div class="elementor-element elementor-element-2b32f6b elementor-widget elementor-widget-text-editor" data-id="2b32f6b" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>Huynh Hieu Travel</p>								</div>
				</div>
				<div class="elementor-element elementor-element-f9e4b76 elementor-widget elementor-widget-heading" data-id="f9e4b76" data-element_type="widget" data-widget_type="heading.default">
				<div class="elementor-widget-container">
					<h1 class="elementor-heading-title elementor-size-default">Designing systems, telling stories, and shaping journeys</h1>				</div>
				</div>
				<div class="elementor-element elementor-element-b89898d elementor-widget elementor-widget-text-editor" data-id="b89898d" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>Kiến tạo hệ thống, kể những câu chuyện và định hình hành trình.</p>								</div>
				</div>
				<div class="elementor-element elementor-element-4846381 elementor-widget elementor-widget-text-editor" data-id="4846381" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>Hơn <strong>10 năm qua</strong>, tôi đã <strong>thiết kế các website chất lượng cao</strong> và tư vấn chiến lược phát triển nội dung số, gắn liền với định hướng Marketing Digital.</p><p>Tôi áp dụng Quản lý hệ thống Lean (Agile, Six Sigma, Kanban) để kết nối giữa chiến lược và thực thi, đảm bảo hiệu quả bền vững.</p><p>Không chỉ dừng ở thiết kế, tôi còn tham gia định hình chiến lược phát triển doanh nghiệp, đặc biệt trong lĩnh vực giáo dục và du lịch.</p>								</div>
				</div>
				</div>
					</div>
				</div>
		<div class="elementor-element elementor-element-3f47213 e-con-full e-flex e-con e-parent" data-id="3f47213" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
				<div class="elementor-element elementor-element-6011df6 elementor-widget elementor-widget-heading" data-id="6011df6" data-element_type="widget" data-widget_type="heading.default">
				<div class="elementor-widget-container">
					<h2 class="elementor-heading-title elementor-size-default">Đối tác thiết kế cho các nhóm làm việc</h2>				</div>
				</div>
		<div class="elementor-element elementor-element-41020e3 e-flex e-con-boxed e-con e-child" data-id="41020e3" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
		<div class="elementor-element elementor-element-5a93cef e-con-full e-flex e-con e-child" data-id="5a93cef" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
				<div class="elementor-element elementor-element-b77ca15 elementor-widget elementor-widget-image" data-id="b77ca15" data-element_type="widget" data-widget_type="image.default">
				<div class="elementor-widget-container">
															<img loading="lazy" decoding="async" width="768" height="768" src="https://media.huynhhieutravel.com/he-thong-fme-768x768.png" class="attachment-medium_large size-medium_large wp-image-13191" alt="Hệ thống FME" srcset="https://media.huynhhieutravel.com/he-thong-fme-768x768.png 768w, https://media.huynhhieutravel.com/he-thong-fme-300x300.png 300w, https://media.huynhhieutravel.com/he-thong-fme-150x150.png 150w, https://media.huynhhieutravel.com/he-thong-fme.png 1024w" sizes="(max-width: 768px) 100vw, 768px" />															</div>
				</div>
				<div class="elementor-element elementor-element-6ea2f30 elementor-widget elementor-widget-heading" data-id="6ea2f30" data-element_type="widget" data-widget_type="heading.default">
				<div class="elementor-widget-container">
					<h2 class="elementor-heading-title elementor-size-default">Hệ thống sinh thái FME Edu</h2>				</div>
				</div>
				<div class="elementor-element elementor-element-dd818c0 elementor-widget elementor-widget-text-editor" data-id="dd818c0" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>At FME, I built not just a website, but a full ecosystem (LMS, CRM, content, strategy).</p>								</div>
