INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (4346, 'Chính sách bảo mật', 'chinh-sach-bao-mat', '
<p>Tại https://huynhhieutravel.com, quyền riêng tư của khách truy cập là vô cùng quan trọng đối với chúng tôi. Tài liệu chính sách bảo mật này phác thảo các loại thông tin cá nhân được nhận và thu thập bởi https://huynhhieutravel.com và cách sử dụng.</p>



<p>Chúng tôi tôn trọng và cam kết sẽ bảo mật những thông tin mang tính riêng tư của bạn. Xin vui lòng đọc bản Chính sách bảo mật dưới đây để hiểu hơn những cam kết mà chúng tôi thực hiện nhằm tôn trọng và bảo vệ quyền lợi của người truy cập. Chính sách bảo mật sẽ giải thích cách chúng tôi tiếp nhận, sử dụng và (trong trường hợp nào đó) tiết lộ thông tin cá nhân của bạn.</p>



<p>Chính sách cũng sẽ giải thích các bước chúng tôi thực hiện để bảo mật thông tin cá nhân của khách hàng. Cuối cùng, Chính sách bảo mật sẽ giải thích quyền lựa chọn của quý khách về việc thu thập, sử dụng và tiết lộ thông tin cá nhân của mình.</p>



<p>Bảo vệ dữ liệu cá nhân và gây dựng được niềm tin cho quý khách là vấn đề rất quan trọng với chúng tôi.</p>



<h2 class="wp-block-heading">Tập tin Đăng nhập</h2>



<p>Giống như nhiều trang web khác, https://huynhhieutravel.com sử dụng các tệp nhật ký. Thông tin bên trong các tệp nhật ký bao gồm địa chỉ giao thức internet (IP), loại trình duyệt, Nhà cung cấp dịch vụ Internet (ISP), đánh dấu ngày / giờ, trang giới thiệu / thoát và số lần nhấp để phân tích xu hướng, quản trị trang web, theo dõi chuyển động của người dùng xung quanh trang web, và thu thập thông tin nhân khẩu học. Địa chỉ IP và các thông tin khác không được liên kết với bất kỳ thông tin nào có thể nhận dạng cá nhân.</p>



<h2 class="wp-block-heading">Cookie</h2>



<p>https://huynhhieutravel.com sử dụng cookie để lưu trữ thông tin về sở thích của khách truy cập, ghi lại thông tin cụ thể của người dùng trên trang nào người dùng truy cập hoặc truy cập, tùy chỉnh nội dung trang Web dựa trên loại trình duyệt của khách truy cập hoặc thông tin khác mà khách truy cập gửi qua trình duyệt của họ .</p>



<h2 class="wp-block-heading">DoubleClick DART Cookie</h2>



<p>Google, với tư cách là nhà cung cấp bên thứ ba, sử dụng cookie để phân phát quảng cáo trên  https://huynhhieutravel.com</p>



<p>Google sử dụng cookie DART cho phép nó phân phát quảng cáo cho người dùng của bạn dựa trên lượt truy cập của họ vào https://huynhhieutravel.com và các trang web khác trên Internet.</p>



<p>Người dùng có thể từ chối sử dụng cookie DART bằng cách truy cập chính sách bảo mật của quảng cáo và mạng Google tại URL sau: <a href="http://www.google.com/privacy_ads.html">http://www.google.com/privacy_ads.html</a></p>



<p>Một số đối tác quảng cáo của chúng tôi có thể sử dụng cookie và tín hiệu trên trang web của chúng tôi. Các đối tác quảng cáo của chúng tôi là <a href="https://www.google.com/adsense">Google Adsense</a></p>



<p>Các máy chủ quảng cáo hoặc mạng quảng cáo của bên thứ ba này sử dụng công nghệ cho các quảng cáo và liên kết xuất hiện trên https://huynhhieutravel.com/ gửi trực tiếp đến trình duyệt của bạn. Họ tự động nhận địa chỉ IP của bạn khi điều này xảy ra. Các công nghệ khác (như cookie, JavaScript hoặc Web Beacons) cũng có thể được sử dụng bởi các mạng quảng cáo của bên thứ ba để đo lường hiệu quả của quảng cáo của họ hoặc để cá nhân hóa nội dung quảng cáo mà bạn nhìn thấy.</p>



<p>https://huynhhieutravel.com không có quyền truy cập hoặc kiểm soát các cookie này được sử dụng bởi các nhà quảng cáo bên thứ ba.</p>



<p>Bạn nên tham khảo các chính sách bảo mật tương ứng của các máy chủ quảng cáo bên thứ ba này để biết thông tin chi tiết hơn về thực tiễn của họ cũng như để được hướng dẫn về cách từ chối một số thực tiễn nhất định. Chính sách bảo mật https://huynhhieutravel.com không áp dụng và chúng tôi không thể kiểm soát các hoạt động của các nhà quảng cáo hoặc trang web khác.</p>



<p>Nếu bạn muốn tắt cookie, bạn có thể làm như vậy thông qua các tùy chọn trình duyệt riêng lẻ. Thông tin chi tiết hơn về quản lý cookie với các trình duyệt web cụ thể có thể được tìm thấy tại các trình duyệt tương ứng bạn sử dụng.</p>



<h2 class="wp-block-heading">Cách liên hệ Huynh Hieu Travel</h2>



<p>Bạn có thể tham khảo thông tin liên hệ tại: <a href="https://huynhhieutravel.com/lien-he/">https://huynhhieutravel.com/lien-he/</a></p>



<p>Thông tin liên hệ Blogger du lịch Huynh Hieu Travel:</p>



<ul class="wp-block-list"><li>Email: huynhtronghieu1911@gmail.com</li><li>Số điện thoại: 01219664444</li><li>Facebook: https://www.fb.com/huynhtronghieu1911</li></ul>



<figure><iframe src="https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d31464.125794061623!2d105.56837100000001!3d9.679697!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0xc1cc72bcc45fcf8a!2sHuynh+Hieu+Travel!5e0!3m2!1svi!2sus!4v1548823435503" width="600" height="450" allowfullscreen=""></iframe></figure>



<p></p>
', 'Tại https://huynhhieutravel.com, quyền riêng tư của khách truy cập là vô cùng quan trọng đối với chúng tôi. Tài liệu chính sách bảo mật này phác thảo các loại thông tin cá nhân được nhận và thu thập bởi https://huynhhieutravel.com và cách sử dụng. Chúng tôi tôn trọng và cam kết sẽ bảo mật những [&hellip;]', 39, 'page', '2019-01-30 04:46:09', '2022-10-26 02:10:16');
